/**
 * Longer, more precise bilingual definitions keyed by glossary `term`
 * (exact match to bilingualGlossary term strings). Merged at runtime over short defs.
 */
export const glossaryLongDefinitions: Record<string, Localized> = {
  // Front-End and test
  RTL: loc(
    "Il Register Transfer Level è l'astrazione sincrona con cui SystemVerilog o VHDL descrivono registri, logica combinatoria e trasferimenti di dati a ogni fronte di clock. È il contratto d'ingresso della sintesi ASIC: reset, clock, larghezze e priorità devono produrre hardware deterministico senza latch, loop combinatori o costrutti non sintetizzabili. In un flusso industriale l'RTL deve superare lint, CDC/RDC, simulazione, formal e LEC contro la netlist, perché un'ambiguità qui si moltiplica durante P&R e signoff. A differenza di una netlist gate-level, l'RTL non istanzia necessariamente celle Liberty né contiene ritardi fisici, ma deve rispettare intenti SDC e UPF che guideranno l'implementazione.",
    "Register Transfer Level is the synchronous abstraction in which SystemVerilog or VHDL describes registers, combinational logic, and data transfers at each clock edge. It is the ASIC synthesis input contract: resets, clocks, widths, and priorities must produce deterministic hardware without latches, combinational loops, or nonsynthesizable constructs. In an industrial flow RTL must pass lint, CDC/RDC, simulation, formal, and LEC against the netlist, because an ambiguity here multiplies through P&R and signoff. Unlike a gate-level netlist, RTL does not necessarily instantiate Liberty cells or contain physical delays, but it must honor the SDC and UPF intent that drives implementation."
  ),
  HDL: loc(
    "Un Hardware Description Language modella struttura, concorrenza e comportamento temporale dell'hardware; SystemVerilog è normato da IEEE 1800 e VHDL da IEEE 1076. La semantica concorrente distingue un HDL da un linguaggio software: assegnamenti non bloccanti, delta cycle e sensitivity possono cambiare il circuito inferito o creare mismatch simulazione-sintesi. Nei progetti ASIC il sottoinsieme sintetizzabile produce RTL e netlist, mentre classi UVM, assertion SVA e delay di testbench restano solo per verifica. Tool come VCS, Xcelium, Questa e i sintetizzatori Design Compiler o Genus devono interpretare coerentemente tipi, signedness, parametri e reset.",
    "A Hardware Description Language models hardware structure, concurrency, and timing behavior; SystemVerilog is standardized by IEEE 1800 and VHDL by IEEE 1076. Concurrent semantics distinguish an HDL from software languages: nonblocking assignments, delta cycles, and sensitivity can alter inferred circuitry or create simulation-to-synthesis mismatches. In ASIC projects the synthesizable subset produces RTL and netlists, while UVM classes, SVA assertions, and testbench delays remain verification-only. Tools such as VCS, Xcelium, Questa, and the Design Compiler or Genus synthesizers must interpret types, signedness, parameters, and resets consistently."
  ),
  FSM: loc(
    "Una Finite State Machine è un circuito sequenziale definito da stato corrente, logica di transizione e uscite, normalmente separato in registri e logica combinatoria. L'encoding binary, one-hot o Gray scambia area, velocità, potenza e robustezza CDC; per esempio one-hot usa N flip-flop per N stati ma spesso accorcia la logica di decode. Default completi evitano latch, mentre stati illegali richiedono recovery esplicita e proprietà SVA come onehot0 o progress per escludere deadlock. Sintesi e formal possono ricodificare la FSM, quindi LEC e vincoli safe-state sono più affidabili del confronto testuale dei bit di stato.",
    "A Finite State Machine is a sequential circuit defined by current state, transition logic, and outputs, normally separated into registers and combinational logic. Binary, one-hot, or Gray encoding trades area, speed, power, and CDC robustness; for example one-hot uses N flip-flops for N states but often shortens decode logic. Complete defaults prevent latches, while illegal states need explicit recovery and SVA properties such as onehot0 or progress to rule out deadlock. Synthesis and formal tools may recode the FSM, so LEC and safe-state constraints are more reliable than textual comparison of state bits."
  ),
  "Clock Gating": loc(
    "Il clock gating arresta la commutazione del clock verso registri inattivi usando una cella ICG caratterizzata, tipicamente latch più AND, e non una porta logica generica. Riduce la potenza dinamica secondo P_dyn = α·C·V²·f sia nei flip-flop sia nell'albero di clock, spesso una quota dominante del consumo digitale. L'enable deve rispettare setup e hold rispetto alla fase inattiva del clock, essere verificato per glitch e restare controllabile nei mode scan tramite test-enable. Sintesi, CTS e STA trattano l'ICG come elemento di clock con check dedicati, mentre un semplice clock-enable sul mux dati risparmia meno potenza e non ferma il tree.",
    "Clock gating stops clock switching to idle registers through a characterized ICG cell, typically a latch plus AND, rather than an arbitrary logic gate. It reduces dynamic power according to P_dyn = α·C·V²·f in both flip-flops and the clock tree, often a dominant share of digital power. The enable must meet setup and hold relative to the inactive clock phase, be checked for glitches, and remain controllable in scan modes through a test enable. Synthesis, CTS, and STA treat the ICG as a clock element with dedicated checks, whereas a data-mux clock enable saves less power and does not stop the tree."
  ),
  DFT: loc(
    "Design For Test è l'insieme di architetture e regole che rendono controllabili e osservabili i difetti di fabbricazione, includendo scan, ATPG, compression, MBIST, boundary scan e test point. L'inserimento converte spesso oltre il 95% dei flip-flop in SDFF e bilancia centinaia di chain rispetto a limiti ATE di pin, memoria e tempo di test. Il signoff misura coverage stuck-at e transition, violazioni DFT, integrità delle chain, protocolli OCC e potenza di shift/capture, con target stuck-at frequentemente superiori al 99%. DFT non è verifica funzionale: un design può passare UVM ma avere difetti non testabili, oppure avere alta test coverage senza essere funzionalmente corretto.",
    "Design For Test is the collection of architectures and rules that make manufacturing defects controllable and observable, including scan, ATPG, compression, MBIST, boundary scan, and test points. Insertion often converts more than 95% of flip-flops to SDFFs and balances hundreds of chains against ATE pin, memory, and test-time limits. Signoff measures stuck-at and transition coverage, DFT-rule violations, chain integrity, OCC protocols, and shift/capture power, with stuck-at targets commonly above 99%. DFT is not functional verification: a design may pass UVM yet contain untestable defects, or achieve high test coverage while remaining functionally wrong."
  ),
  ATPG: loc(
    "Automatic Test Pattern Generation risolve vettori che eccitano un modello di guasto interno e propagano il suo effetto a un punto osservabile attraverso le scan chain. I modelli comuni sono stuck-at, transition, path-delay e bridging; coverage = guasti rilevati / guasti testabili, separando redundant, aborted e untestable. Tessent, Synopsys TestMAX e Cadence Modus compattano pattern sotto vincoli ATE, masking X e limiti di toggle per evitare droop durante shift o capture. Un 99% stuck-at non implica 99% transition, e pattern generati su una netlist precedente all'ECO non costituiscono signoff della netlist finale.",
    "Automatic Test Pattern Generation solves vectors that excite an internal fault model and propagate its effect to an observable point through scan chains. Common models include stuck-at, transition, path-delay, and bridging; coverage equals detected faults divided by testable faults, with redundant, aborted, and untestable classes reported separately. Tessent, Synopsys TestMAX, and Cadence Modus compact patterns under ATE, X-masking, and toggle constraints to prevent droop during shift or capture. A 99% stuck-at result does not imply 99% transition coverage, and patterns generated on a pre-ECO netlist do not sign off the final netlist."
  ),
  MBIST: loc(
    "Memory Built-In Self Test integra controller, address generator, data generator e comparator per collaudare SRAM e altre macro che le scan chain non osservano efficacemente. Algoritmi March C- o March 13N applicano sequenze di lettura/scrittura ascendenti e discendenti per rilevare stuck-at, transition, coupling e address-decoder fault. Il controller deve coprire tutte le configurazioni, frequenze e power domain, rispettare timing macro e limitare corrente simultanea quando molte memorie entrano in test. MBIST rileva il guasto, mentre BISR usa signature e fuse/eFuse per sostituire row o column difettose con spare e migliorare lo yield.",
    "Memory Built-In Self Test integrates a controller, address generator, data generator, and comparator to test SRAMs and other macros that scan chains cannot observe efficiently. March C- or March 13N algorithms apply ascending and descending read/write sequences to detect stuck-at, transition, coupling, and address-decoder faults. The controller must cover every configuration, frequency, and power domain, honor macro timing, and limit simultaneous current when many memories enter test. MBIST detects the fault, whereas BISR uses signatures and fuse or eFuse data to replace faulty rows or columns with spares and improve yield."
  ),
  "Scan Chain": loc(
    "Una scan chain collega in serie gli SDFF in modalità test, trasformando lo stato sequenziale interno in uno shift register controllabile da scan_in e osservabile su scan_out. Il numero e la lunghezza delle chain determinano cicli ATE circa pari a pattern × max_length, mentre compression EDT collega poche chain esterne a molte chain interne. Il reorder fisico riduce wirelength e congestion, ma stitching tra domini di clock richiede lock-up latch per proteggere hold durante scan shift. Signoff verifica continuità, polarità clock, scan-enable, chain balancing e hold in modalità shift, non soltanto la connettività logica.",
    "A scan chain serially connects SDFFs in test mode, turning internal sequential state into a shift register controllable at scan_in and observable at scan_out. Chain count and length set ATE cycles at roughly patterns times maximum length, while EDT compression connects a few external chains to many internal chains. Physical reordering reduces wirelength and congestion, but stitching across clock domains requires lock-up latches to protect hold during scan shift. Signoff checks continuity, clock polarity, scan enable, chain balance, and shift-mode hold rather than only logical connectivity."
  ),
  JTAG: loc(
    "JTAG è l'interfaccia IEEE 1149.1 basata su TAP state machine e segnali TCK, TMS, TDI, TDO, con TRST opzionale. Le istruzioni EXTEST, SAMPLE/PRELOAD e BYPASS pilotano boundary-scan cell sugli I/O per trovare open e short di scheda senza accesso fisico ai pin. In un ASIC il TAP può anche instradare debug, IJTAG IEEE 1687 o accesso MBIST, ma sicurezza e ownership dei registri devono essere definiti per il prodotto. JTAG non sostituisce la scan interna ATPG: boundary scan osserva soprattutto interconnessioni package/PCB e usa un protocollo seriale molto più lento.",
    "JTAG is the IEEE 1149.1 interface built around a TAP state machine and TCK, TMS, TDI, and TDO signals, with optional TRST. EXTEST, SAMPLE/PRELOAD, and BYPASS instructions control boundary-scan cells on I/Os to find board opens and shorts without physical probe access. In an ASIC the TAP may also route debug, IEEE 1687 IJTAG, or MBIST access, but register ownership and product security must be defined. JTAG does not replace internal ATPG scan: boundary scan primarily observes package and PCB interconnect and runs through a much slower serial protocol."
  ),

  // Verification
  UVM: loc(
    "Universal Verification Methodology è lo standard Accellera/SystemVerilog per costruire testbench riusabili con sequence, driver, monitor, agent, scoreboard e factory. Transaction-level modeling separa lo stimolo dai pin del DUT e consente constrained-random, configurazione gerarchica e riuso da IP a SoC. Il closure industriale combina pass/fail dello scoreboard, assertion SVA, code coverage e functional coverage, con seed riproducibili e regressioni su VCS, Xcelium o Questa. UVM è una metodologia di simulazione, non una prova esaustiva: formal copre proprietà su tutti gli input legali e STA copre timing che un testbench RTL non modella.",
    "Universal Verification Methodology is the Accellera and SystemVerilog standard for reusable testbenches built from sequences, drivers, monitors, agents, scoreboards, and the factory. Transaction-level modeling separates stimulus from DUT pins and enables constrained random generation, hierarchical configuration, and reuse from IP to SoC. Industrial closure combines scoreboard pass/fail, SVA assertions, code coverage, and functional coverage with reproducible seeds and regressions on VCS, Xcelium, or Questa. UVM is a simulation methodology, not an exhaustive proof: formal covers properties over all legal inputs and STA covers timing that an RTL testbench does not model."
  ),
  SVA: loc(
    "SystemVerilog Assertions esprime proprietà temporali immediate o concorrenti mediante sequence, property e operatori come |->, |=> e ##. Le assertion controllano protocolli, latenza, mutual exclusion, ordering, reset e invarianti FSM sia in simulazione sia nei motori formal. Una proprietà deve definire clock, disable iff e assunzioni ambientali corrette, altrimenti può passare vacuamente o generare falsi fail durante reset e X propagation. Le cover property dimostrano raggiungibilità, mentre le assert property cercano controesempi; nessuna delle due equivale ai covergroup di functional coverage UVM.",
    "SystemVerilog Assertions expresses immediate or concurrent temporal properties using sequences, properties, and operators such as |->, |=>, and ##. Assertions check protocols, latency, mutual exclusion, ordering, reset, and FSM invariants in both simulation and formal engines. A property must define its clock, disable iff condition, and environment assumptions correctly or it may pass vacuously or fail spuriously during reset and X propagation. Cover properties demonstrate reachability, whereas assert properties seek counterexamples; neither is equivalent to UVM functional-coverage covergroups."
  ),
  LEC: loc(
    "Logic Equivalence Check è una prova formale che due rappresentazioni, tipicamente RTL e netlist sintetizzata oppure netlist pre e post-ECO, implementino la stessa funzione osservabile. Conformal, Formality e Questa Equivalence costruiscono compare point, mappano registri e dimostrano coni logici senza enumerare vettori di test. Clock gating, retiming, datapath aritmetici, scan e power intent richiedono setup o modelli dedicati; black box e punti non confrontati devono essere contabilizzati, non ignorati. Un pass LEC non prova timing, CDC o correttezza rispetto alla specifica, ma impedisce che sintesi, DFT o ECO alterino involontariamente una funzione RTL già verificata.",
    "Logic Equivalence Check formally proves that two representations, typically RTL versus a synthesized netlist or pre-ECO versus post-ECO netlists, implement the same observable function. Conformal, Formality, and Questa Equivalence create compare points, map registers, and prove logic cones without enumerating test vectors. Clock gating, retiming, arithmetic datapaths, scan, and power intent require dedicated setup or models; black boxes and unmatched points must be accounted for rather than ignored. A passing LEC result proves neither timing, CDC, nor correctness against the specification, but it prevents synthesis, DFT, or ECO from unintentionally changing already-verified RTL behavior."
  ),
  CDC: loc(
    "Clock Domain Crossing è l'analisi strutturale e funzionale dei segnali che passano tra clock asincroni o con relazione non garantita. Un singolo bit di livello usa tipicamente due o più flip-flop synchronizer con MTBF proporzionale a exp(Tres/τ)/(fclk·fdata), mentre pulse, bus e dati continui richiedono handshake, toggle, Gray counter o asynchronous FIFO. SpyGlass CDC, Questa CDC e VC CDC verificano struttura, reconvergence, coherency, reset e constraint dei clock, spesso insieme a simulation assertion. Due flop non rendono coerente un bus e un false path SDC rimuove solo l'analisi timing, non elimina metastabilità né prova il protocollo.",
    "Clock Domain Crossing is the structural and functional analysis of signals moving between asynchronous clocks or clocks without a guaranteed relationship. A single level bit typically uses two or more synchronizer flip-flops with MTBF proportional to exp(Tres/τ)/(fclk·fdata), while pulses, buses, and continuous data require handshakes, toggles, Gray counters, or asynchronous FIFOs. SpyGlass CDC, Questa CDC, and VC CDC check structure, reconvergence, coherency, resets, and clock constraints, often together with simulation assertions. Two flip-flops do not make a bus coherent, and an SDC false path only removes timing analysis; it neither eliminates metastability nor proves the protocol."
  ),
  RDC: loc(
    "Reset Domain Crossing analizza segnali tra registri controllati da reset differenti per sorgente, polarità, sincronizzazione o sequenza di rilascio. L'assert asincrono è comune, ma il deassert deve essere sincronizzato in ciascun clock domain per evitare recovery/removal violation e stati parzialmente rilasciati. Un dominio che esce dal reset mentre il producer resta resettato può campionare valori incoerenti o X, quindi tool come Questa RDC e VC SpyGlass RDC verificano reset tree, crossing e power sequence. RDC è distinto da CDC: anche con lo stesso clock due reset indipendenti creano un crossing, e un sincronizzatore dati non risolve automaticamente il problema di reset.",
    "Reset Domain Crossing analyzes signals between registers controlled by resets that differ in source, polarity, synchronization, or release sequence. Asynchronous assertion is common, but deassertion must be synchronized in each clock domain to avoid recovery/removal violations and partially released state. A domain leaving reset while its producer remains reset can sample incoherent values or Xs, so tools such as Questa RDC and VC SpyGlass RDC check reset trees, crossings, and power sequences. RDC differs from CDC: even under one clock, two independent resets create a crossing, and a data synchronizer does not automatically solve the reset problem."
  ),
  Formal: loc(
    "La verifica formale usa model checking, SAT/SMT e induction per dimostrare assertion o produrre controesempi su tutti i comportamenti ammessi dal modello. È particolarmente efficace per arbiter, FIFO, protocolli, sicurezza FSM, deadlock e equivalenza, dove la simulazione campiona solo una frazione dello spazio degli stati. Assumption errate possono rendere una prova vacua, mentre state-space explosion richiede abstraction, cutpoint, assume-guarantee e proof decomposition in JasperGold, VC Formal o Questa Formal. Una proprietà proven è valida entro modello, bound e assunzioni dichiarate; non sostituisce analog signoff, STA o una specifica incompleta.",
    "Formal verification uses model checking, SAT/SMT, and induction to prove assertions or generate counterexamples over every behavior admitted by the model. It is especially effective for arbiters, FIFOs, protocols, FSM safety, deadlock, and equivalence, where simulation samples only a fraction of the state space. Incorrect assumptions can make a proof vacuous, while state-space explosion requires abstraction, cutpoints, assume-guarantee reasoning, and proof decomposition in JasperGold, VC Formal, or Questa Formal. A proven property is valid within its declared model, bound, and assumptions; it does not replace analog signoff, STA, or a missing specification."
  ),
  Lint: loc(
    "Il lint RTL è un'analisi statica che trova costrutti rischiosi senza eseguire vettori: latch inferiti, width truncation, signedness, case incompleti, multi-driver, loop combinatori e reset incoerenti. Regole di SpyGlass Lint, Questa Lint o Verissimo codificano sia errori sintetizzabili sia policy di progetto, con severity e waiver tracciati. Il signoff richiede zero errori e waiver motivati con owner e revisione, perché silenziare globalmente una regola può nascondere mismatch simulazione-sintesi o X optimism. Il lint non sostituisce compilazione, CDC, formal o LEC: segnala pattern strutturali, ma non dimostra la funzione né la chiusura temporale.",
    "RTL lint is static analysis that finds risky constructs without applying vectors: inferred latches, width truncation, signedness issues, incomplete cases, multiple drivers, combinational loops, and inconsistent resets. Rules in SpyGlass Lint, Questa Lint, or Verissimo encode both synthesizable defects and project policies, with tracked severities and waivers. Signoff requires zero errors and justified waivers with owners and review, because globally suppressing a rule can hide simulation-to-synthesis mismatches or X optimism. Lint does not replace compilation, CDC, formal, or LEC: it flags structural patterns but proves neither function nor timing closure."
  ),
  Coverage: loc(
    "Coverage misura quale parte del piano di verifica è stata esercitata, combinando code coverage di line, branch, expression, toggle e FSM con functional coverage definita da coverpoint e cross. La percentuale utile è covered bins / reachable planned bins; bin illegali o irraggiungibili vanno giustificati, non esclusi per alzare artificialmente il numero. Un closure industriale collega ogni feature e corner case a test, assertion o cover bin e analizza coverage merge su regressioni con seed differenti, spesso puntando al 100% strutturale e almeno 95% funzionale secondo policy. Coverage elevata non prova assenza di bug: indica stimolo o osservazione, mentre scoreboard, assertion e formal determinano se il comportamento era corretto.",
    "Coverage measures how much of the verification plan has been exercised by combining line, branch, expression, toggle, and FSM code coverage with functional coverage defined by coverpoints and crosses. The meaningful ratio is covered bins divided by reachable planned bins; illegal or unreachable bins must be justified rather than excluded merely to inflate the number. Industrial closure maps every feature and corner case to a test, assertion, or cover bin and analyzes merged coverage across different regression seeds, often targeting 100% structural and at least 95% functional coverage by policy. High coverage does not prove absence of bugs: it indicates stimulation or observation, while scoreboards, assertions, and formal determine whether behavior was correct."
  ),
  CLP: loc(
    "Common o Conformal Low Power indica la verifica statica e di equivalenza dell'intento IEEE 1801 UPF rispetto a RTL e netlist implementata. Il controllo assicura che ogni crossing di dominio riceva level shifter e isolation corretti, che retention save/restore, supply set e power switch corrispondano alla power-state table. Cadence Conformal Low Power, Synopsys VC LP e Siemens Questa Power Aware trovano missing strategy, clamp errato, always-on path interrotto e corruption non prevista. CLP non è power analysis in watt né IR drop: verifica semantica e implementazione low-power, e un fail può bloccare l'handoff PD anche se LEC logico standard passa.",
    "Common or Conformal Low Power denotes static and equivalence verification of IEEE 1801 UPF intent against RTL and the implemented netlist. It ensures that every domain crossing receives the correct level shifter and isolation, and that retention save/restore, supply sets, and power switches match the power-state table. Cadence Conformal Low Power, Synopsys VC LP, and Siemens Questa Power Aware find missing strategies, wrong clamps, broken always-on paths, and unexpected corruption. CLP is neither wattage analysis nor IR drop: it verifies low-power semantics and implementation, and a failure can block PD handoff even when ordinary logical LEC passes."
  ),

  // Exchange and activity files
  SDC: loc(
    "Synopsys Design Constraints è il formato Tcl che descrive clock, I/O environment, eccezioni, operating mode e limiti elettrici usati da sintesi, P&R e STA. Comandi come create_clock, create_generated_clock, set_input_delay, set_clock_uncertainty e set_case_analysis definiscono il grafo temporale, mentre false e multicycle path devono riflettere impossibilità funzionali reali. Un clock mancante rende path unconstrained e può produrre WNS apparentemente pulito, quindi signoff include check_timing, coverage dei constraint e confronto tra versioni SDC. SDC non contiene delay estratti o modelli cella: questi arrivano da SPEF e Liberty, combinati per ciascuno scenario MMMC.",
    "Synopsys Design Constraints is the Tcl format describing clocks, I/O environment, exceptions, operating modes, and electrical limits used by synthesis, P&R, and STA. Commands such as create_clock, create_generated_clock, set_input_delay, set_clock_uncertainty, and set_case_analysis define the timing graph, while false and multicycle paths must reflect genuine functional impossibilities. A missing clock leaves paths unconstrained and can produce deceptively clean WNS, so signoff includes check_timing, constraint coverage, and SDC version comparison. SDC contains neither extracted delays nor cell models; those come from SPEF and Liberty and are combined for each MMMC scenario."
  ),
  LIB: loc(
    "Un file Liberty .lib descrive per ogni cella pin, funzione booleana, timing arc, constraint setup/hold, potenza, leakage, capacitance e limiti max_transition o max_capacitance. Le tabelle NLDM indicizzano delay e slew per input transition e output load, mentre CCS/ECSM e LVF aggiungono forme d'onda di corrente e variazione statistica. Ogni combinazione PVT e famiglia HVT/SVT/LVT richiede una vista coerente, spesso compilata in .db per PrimeTime o Design Compiler. Liberty è un modello caratterizzato, non la geometria LEF: usare corner, unità o cell footprint sbagliati falsifica sintesi e STA anche se la netlist compila.",
    "A Liberty .lib file describes each cell's pins, Boolean function, timing arcs, setup/hold constraints, power, leakage, capacitance, and limits such as max_transition or max_capacitance. NLDM tables index delay and slew by input transition and output load, while CCS/ECSM and LVF add current waveforms and statistical variation. Every PVT combination and HVT/SVT/LVT family needs a consistent view, often compiled to .db for PrimeTime or Design Compiler. Liberty is a characterized model rather than LEF geometry: wrong corners, units, or cell footprints corrupt synthesis and STA even if the netlist compiles."
  ),
  LEF: loc(
    "Library Exchange Format fornisce a P&R una vista geometrica astratta del processo e delle celle senza consegnare tutti i poligoni GDS. Il technology LEF definisce layer, pitch, direction, via, spacing e site, mentre macro/cell LEF definisce SIZE, CLASS, PIN, PORT e OBS. Router e legalizer usano queste forme per track alignment, pin access e blockage, quindi incoerenze LEF-GDS causano DRC o LVS soltanto a fine flusso. LEF non contiene connettività completa del design come DEF né timing come Liberty; le tre viste devono condividere nomi di macro e pin.",
    "Library Exchange Format gives P&R an abstract geometric view of the process and cells without delivering every GDS polygon. Technology LEF defines layers, pitch, direction, vias, spacing, and sites, while macro or cell LEF defines SIZE, CLASS, PIN, PORT, and OBS. Routers and legalizers use these shapes for track alignment, pin access, and blockages, so LEF-to-GDS inconsistencies cause DRC or LVS failures late in the flow. LEF contains neither full design connectivity like DEF nor timing like Liberty; all three views must share macro and pin names."
  ),
  DEF: loc(
    "Design Exchange Format è la descrizione fisica ASCII di un'istanza di progetto, con DIEAREA, ROWS, TRACKS, COMPONENTS, PINS, NETS, SPECIALNETS, VIAS, BLOCKAGES e REGIONS. È il checkpoint interoperabile tra floorplan, placement, CTS e routing e registra coordinate, orientamento, stato FIXED/PLACED e connessioni PG. Versione, database unit e naming devono combaciare con LEF e netlist; un mismatch di unità o bus delimiter può spostare geometrie o spezzare connettività. A differenza di GDSII, DEF conserva semantica di oggetti e net ma non tutti i dettagli mask-ready delle celle e del fill.",
    "Design Exchange Format is the ASCII physical description of a design instance, including DIEAREA, ROWS, TRACKS, COMPONENTS, PINS, NETS, SPECIALNETS, VIAS, BLOCKAGES, and REGIONS. It is the interoperable checkpoint across floorplanning, placement, CTS, and routing and records coordinates, orientation, FIXED or PLACED status, and power connections. Its version, database units, and naming must match LEF and the netlist; a unit or bus-delimiter mismatch can move geometry or break connectivity. Unlike GDSII, DEF preserves object and net semantics but not every mask-ready detail of cells and fill."
  ),
  SPEF: loc(
    "Standard Parasitic Exchange Format rappresenta la rete RC estratta del layout con capacitance verso ground, coupling capacitance, resistance e connessioni interne per net. StarRC, Quantus o Calibre xACT lo generano per corner RC, e PrimeTime o Tempus lo annotano sulla netlist per STA e signal integrity post-route. Il delay di una rete distribuita è approssimabile con momenti Elmore ΣRi·Cdownstream, ma il signoff usa reduction e modelli coupled più accurati. SPEF fill-inclusive, naming-map e unità devono corrispondere al design; net non annotate o coupling eliminato possono sottostimare delay, crosstalk e consumo.",
    "Standard Parasitic Exchange Format represents an extracted layout RC network with ground capacitance, coupling capacitance, resistance, and internal net connections. StarRC, Quantus, or Calibre xACT generates it for each RC corner, and PrimeTime or Tempus annotates it onto the netlist for post-route STA and signal integrity. Distributed-net delay can be approximated by Elmore moments ΣRi·Cdownstream, but signoff uses more accurate reduction and coupled models. Fill-inclusive extraction, naming maps, and units must match the design; unannotated nets or removed coupling can underestimate delay, crosstalk, and power."
  ),
  SDF: loc(
    "Standard Delay Format trasporta delay min/typ/max di cella e interconnect, timing check e conditional arc da annotare in una simulazione gate-level. Il simulatore applica l'SDF alla netlist per verificare reset, X propagation, scan e sequenze sensibili al timing con ritardi post-layout. Errori di instance path o arc producono bassa annotation coverage, quindi il log deve riportare percentuali prossime al 100% per gli oggetti previsti. SDF è una fotografia di delay per simulazione event-driven e non sostituisce STA MMMC, che analizza esaustivamente tutti i path e modella OCV, SI e CPPR.",
    "Standard Delay Format carries min/typ/max cell and interconnect delays, timing checks, and conditional arcs for gate-level simulation annotation. A simulator applies SDF to the netlist to verify reset, X propagation, scan, and timing-sensitive sequences with post-layout delays. Instance-path or arc mismatches cause low annotation coverage, so logs should report percentages near 100% for intended objects. SDF is an event-driven simulation delay snapshot and does not replace MMMC STA, which exhaustively analyzes all paths and models OCV, SI, and CPPR."
  ),
  UPF: loc(
    "Unified Power Format, standard IEEE 1801, descrive power domain, supply net e set, power state, isolation, level shifting, retention, always-on logic e power switch separatamente dall'RTL funzionale. Sintesi e P&R materializzano questa intenzione inserendo celle speciali e collegando primary e secondary PG, mentre simulation power-aware corrompe i domini spenti per verificare i protocolli. La power-state table deve escludere combinazioni illegali e definire sequenze di clamp, save, switch e restore; errori causano X leakage, overstress o perdita di stato in silicio. UPF non è una mappa fisica della PDN né un report di potenza: è il contratto semantico low-power che CLP confronta tra RTL, netlist e implementazione.",
    "Unified Power Format, standardized as IEEE 1801, describes power domains, supply nets and sets, power states, isolation, level shifting, retention, always-on logic, and power switches separately from functional RTL. Synthesis and P&R materialize this intent by inserting special cells and connecting primary and secondary power grids, while power-aware simulation corrupts shut-down domains to verify protocols. The power-state table must exclude illegal combinations and define clamp, save, switch, and restore sequencing; mistakes cause X leakage, overstress, or state loss in silicon. UPF is neither a physical PDN map nor a power report: it is the low-power semantic contract that CLP compares across RTL, netlist, and implementation."
  ),
  GDSII: loc(
    "GDSII o STREAM è il formato binario gerarchico che consegna boundary, path, text e reference di tutte le geometrie mask-ready usando coppie layer/datatype. Il tapeout merge combina core, IP hard macro, IO, fill, seal ring e marker e applica il layer map del PDK prima di checksum e consegna foundry. Calibre, ICV o Pegasus eseguono DRC/LVS sul database merged, che per SoC avanzati può raggiungere decine o centinaia di gigabyte e richiedere fracture in mask shop. GDSII non contiene intenti RTL, timing o net semantics affidabili; OASIS conserva la stessa geometria con compressione e costrutti ripetitivi più efficienti.",
    "GDSII or STREAM is the hierarchical binary format delivering boundaries, paths, text, and references for all mask-ready geometry through layer and datatype pairs. Tapeout merge combines the core, hard IP, I/O, fill, seal ring, and markers and applies the PDK layer map before checksum and foundry delivery. Calibre, ICV, or Pegasus runs DRC/LVS on the merged database, which can reach tens or hundreds of gigabytes for advanced SoCs and later be fractured by the mask shop. GDSII carries neither RTL intent, timing, nor reliable net semantics; OASIS preserves equivalent geometry with more efficient compression and repetition constructs."
  ),
  OASIS: loc(
    "Open Artwork System Interchange Standard è un formato layout mask-ready progettato come successore compatto di GDSII con repetition, variable-length encoding e compressione più efficienti. Conserva gerarchia, coordinate, layer/datatype, polygon e text necessari al signoff, ma può ridurre dimensione e I/O di circa 5–10× su layout ripetitivi. Stream-out e read-back devono essere confrontati con checksum, cell count e XOR geometrico perché mapping o feature non supportate possono alterare il database consegnato. OASIS non è un formato di placement come DEF: è una rappresentazione finale di geometrie, equivalente per DRC/LVS e mask generation quando il toolchain foundry è qualificato.",
    "Open Artwork System Interchange Standard is a mask-ready layout format designed as a compact GDSII successor with more efficient repetition, variable-length encoding, and compression. It preserves hierarchy, coordinates, layer/datatype, polygons, and text needed for signoff while often reducing size and I/O by roughly 5–10× on repetitive layouts. Stream-out and read-back must be compared through checksums, cell counts, and geometric XOR because mapping or unsupported features can alter delivered data. OASIS is not a placement format like DEF: it is a final geometry representation equivalent for DRC/LVS and mask generation when the foundry toolchain is qualified."
  ),
  VCD: loc(
    "Value Change Dump è il formato IEEE testuale che registra timestamp e ogni transizione di valore dei signal selezionati durante simulazione. Da una finestra VCD realistica i tool derivano toggle, simultaneità e corrente per power estimation e dynamic IR, preservando burst di di/dt che una media può nascondere. Dump su tutto il SoC per milioni di cicli può diventare terabyte, quindi scope, finestra, timescale e mapping RTL-gate devono essere controllati e documentati. VCD offre sequenza temporale completa ma poca compressione; SAIF conserva statistiche aggregate più piccole e FSDB comprime waveform mantenendo debug temporale.",
    "Value Change Dump is the textual IEEE format that records timestamps and every value transition of selected signals during simulation. From a realistic VCD window, tools derive toggles, simultaneity, and current for power estimation and dynamic IR while preserving di/dt bursts that averages can hide. Full-SoC dumps over millions of cycles can reach terabytes, so scope, window, timescale, and RTL-to-gate mapping must be controlled and documented. VCD provides a complete temporal sequence with little compression; SAIF stores smaller aggregate statistics, while FSDB compresses waveforms and retains temporal debug."
  ),
  FSDB: loc(
    "Fast Signal Database è un formato waveform binario compresso dell'ecosistema Verdi usato per debug di simulazioni RTL e gate-level molto grandi. Memorizza transizioni, gerarchia e tipi con accesso indicizzato, riducendo spazio e tempo di navigazione rispetto a VCD pur mantenendo la cronologia necessaria a glitch e causalità. Tool di power possono leggere FSDB per activity annotation, ma versione, scope, timescale e corrispondenza dei nomi alla netlist determinano la coverage effettiva. FSDB non è SAIF: il primo conserva waveform temporali dettagliate, il secondo principalmente toggle count e static probability aggregate.",
    "Fast Signal Database is a compressed binary waveform format in the Verdi ecosystem used to debug very large RTL and gate-level simulations. It stores transitions, hierarchy, and types with indexed access, reducing space and navigation time relative to VCD while retaining the history needed for glitch and causality analysis. Power tools can read FSDB for activity annotation, but version, scope, timescale, and name correspondence to the netlist determine effective coverage. FSDB is not SAIF: the former retains detailed temporal waveforms, while the latter primarily stores aggregate toggle counts and static probabilities."
  ),
  SAIF: loc(
    "Switching Activity Interchange Format riassume per ogni net durata in 0, 1 e X, toggle count e talvolta glitch activity su una finestra di simulazione. Sintesi e power analysis usano α derivato dal SAIF in P_dyn = α·C·V²·f per ottimizzare clock gating, sizing e stima media di consumo. Name mapping, gerarchia, durata e mode devono essere verificati, perché net non annotate ricevono toggle di default e possono falsare il budget di potenza. SAIF è molto più compatto di VCD o FSDB ma perde correlazione temporale e simultaneità, quindi non descrive bene picchi dynamic IR o SSO.",
    "Switching Activity Interchange Format summarizes each net's time at 0, 1, and X, toggle count, and sometimes glitch activity over a simulation window. Synthesis and power analysis use SAIF-derived α in P_dyn = α·C·V²·f to optimize clock gating, sizing, and average power. Name mapping, hierarchy, duration, and operating mode must be checked because unannotated nets receive default toggles and can distort the power budget. SAIF is far smaller than VCD or FSDB but loses temporal correlation and simultaneity, so it does not represent dynamic-IR peaks or SSO well."
  ),
  "Verilog Netlist": loc(
    "Una Verilog netlist gate-level istanzia standard cell, macro, pad e connessioni prodotte da sintesi o P&R, senza la struttura comportamentale originale dell'RTL. È l'handoff logico FE→PD e, dopo route/ECO, la base comune per LEC, STA, ATPG, gate-level simulation e LVS source. I nomi di cella e pin devono esistere nelle viste Liberty, LEF e CDL/SPICE corrette, mentre tie, filler o physical-only cell possono essere trattate diversamente secondo il consumer. La netlist non contiene geometria né RC reali: DEF/GDS forniscono placement e layout, SPEF annota parassiti e SDF può serializzare delay di simulazione.",
    "A gate-level Verilog netlist instantiates standard cells, macros, pads, and connectivity produced by synthesis or P&R without the original behavioral RTL structure. It is the logical FE-to-PD handoff and, after route or ECO, the common basis for LEC, STA, ATPG, gate-level simulation, and the LVS source. Cell and pin names must exist in the matching Liberty, LEF, and CDL/SPICE views, while tie, filler, or physical-only cells may be handled differently by each consumer. The netlist contains neither geometry nor real RC: DEF/GDS provides placement and layout, SPEF annotates parasitics, and SDF can serialize simulation delays."
  ),
  "Tech File": loc(
    "Un technology file traduce il processo foundry in layer, via, resistività, dielectric, spacing, antenna, density ed EM rule leggibili da uno specifico tool. Le forme includono technology LEF per P&R, Synopsys .tf o NXTGRD/ITF e qrcTechFile per extraction, oltre ai runset DRC/LVS, e non sono intercambiabili senza conversione qualificata. Versione e metal stack devono restare locked tra route, extraction e signoff; una via resistance o thickness incoerente altera timing, IR ed EM anche con DRC pulito. Il tech file descrive il processo, mentre LEF di cella descrive macro astratte e il PDK è il pacchetto più ampio che include entrambi con Liberty, deck e documentazione.",
    "A technology file translates the foundry process into tool-readable layers, vias, resistivity, dielectrics, spacing, antenna, density, and EM rules. Forms include technology LEF for P&R, Synopsys .tf or NXTGRD/ITF and qrcTechFile for extraction, plus DRC/LVS runsets, and they are not interchangeable without qualified conversion. Version and metal stack must remain locked across routing, extraction, and signoff; inconsistent via resistance or thickness changes timing, IR, and EM even with clean DRC. A tech file describes the process, while cell LEF describes abstract macros and the PDK is the broader package containing both along with Liberty, decks, and documentation."
  ),

  // Timing and signoff analysis
  STA: loc(
    "Static Timing Analysis propaga arrival time e required time su tutti gli archi del timing graph senza richiedere vettori di simulazione. Per un check setup lo slack è required arrival − actual arrival, mentre per hold la convenzione del tool assicura comunque che slack negativo significhi violazione. PrimeTime e Tempus analizzano ogni mode e corner MMMC con Liberty, SDC, SPEF, SI, OCV e CPPR, riportando path reg-to-reg, I/O, recovery/removal e clock-gating. STA è esaustiva per i path correttamente vincolati ma non prova funzionalità o crossing asincroni, quindi unconstrained path ed eccezioni non validate invalidano un signoff apparentemente verde.",
    "Static Timing Analysis propagates arrival and required times through every arc in a timing graph without simulation vectors. For a setup check, slack is required arrival minus actual arrival, while for hold the tool convention still ensures that negative slack means a violation. PrimeTime and Tempus analyze every MMMC mode and corner with Liberty, SDC, SPEF, SI, OCV, and CPPR, reporting register-to-register, I/O, recovery/removal, and clock-gating paths. STA is exhaustive for correctly constrained paths but proves neither functionality nor asynchronous crossings, so unconstrained paths and unvalidated exceptions invalidate an apparently green signoff."
  ),
  WNS: loc(
    "Worst Negative Slack è il valore minimo di slack tra tutti i path di un gruppo, scenario e tipo di check e identifica la singola violazione più grave. WNS = −80 ps significa che almeno un endpoint manca il requisito di 80 ps, mentre WNS ≥ 0 indica assenza di slack negativo soltanto nell'insieme analizzato. Il closure industriale richiede WNS non negativo per setup, hold, recovery/removal e gating in ogni scenario MMMC, dopo SI e variation signoff. WNS non misura l'ampiezza complessiva del problema: un solo path a −80 ps e diecimila path a −20 ps hanno lo stesso WNS massimo ma TNS e costo ECO molto diversi.",
    "Worst Negative Slack is the minimum slack across all paths in a group, scenario, and check type and identifies the single worst violation. WNS = −80 ps means at least one endpoint misses its requirement by 80 ps, while WNS ≥ 0 indicates no negative slack only within the analyzed set. Industrial closure requires nonnegative WNS for setup, hold, recovery/removal, and gating across every MMMC scenario after SI and variation signoff. WNS does not measure total problem size: one path at −80 ps and ten thousand paths at −20 ps may share a similar worst value but have very different TNS and ECO cost."
  ),
  TNS: loc(
    "Total Negative Slack è la somma degli slack minori di zero su endpoint o path secondo la modalità di reporting del tool. Se tre endpoint hanno −40, −20 e +10 ps, il TNS è −60 ps, non −50 ps, perché gli slack positivi non compensano le violazioni. TNS guida l'ottimizzazione globale di synthesis e P&R e rivela se il timing debt è diffuso anche quando il WNS migliora rapidamente. Il signoff richiede tipicamente TNS = 0 insieme a WNS ≥ 0 per ogni path group e scenario; confronti tra run sono validi solo con identici constraint, corner e conteggio endpoint.",
    "Total Negative Slack is the sum of slacks below zero across endpoints or paths according to the tool's reporting mode. If three endpoints have −40, −20, and +10 ps, TNS is −60 ps rather than −50 ps because positive slack does not cancel violations. TNS guides global synthesis and P&R optimization and reveals widespread timing debt even when WNS improves quickly. Signoff typically requires TNS = 0 together with WNS ≥ 0 for every path group and scenario; run-to-run comparisons are valid only with identical constraints, corners, and endpoint counting."
  ),
  Setup: loc(
    "Il setup check richiede che il dato lanciato arrivi e si stabilizzi almeno t_setup prima del fronte di capture pertinente. In forma semplificata Tclk ≥ Tcq + Tcomb + Tsetup + uncertainty − useful_skew, includendo latency, derate e coupling secondo il modello STA. I path setup peggiorano spesso a corner slow, bassa V e temperatura elevata, ma temperature inversion ai nodi avanzati impone anche corner freddi qualificati. Fix comuni sono upsizing, LVT swap, buffering, logic restructuring o useful skew; aggiungere delay, tipico fix hold, generalmente peggiora setup.",
    "A setup check requires launched data to arrive and settle at least t_setup before the relevant capture edge. In simplified form Tclk ≥ Tcq + Tcomb + Tsetup + uncertainty − useful_skew, including latency, derates, and coupling in the STA model. Setup paths often worsen at slow process, low voltage, and high temperature, but temperature inversion at advanced nodes also requires qualified cold corners. Common fixes include upsizing, LVT swaps, buffering, logic restructuring, or useful skew; adding delay, the typical hold fix, generally worsens setup."
  ),
  Hold: loc(
    "Il hold check richiede che il dato precedente resti stabile per almeno t_hold dopo lo stesso fronte di capture, ed è quindi un vincolo di contaminazione minima indipendente dal periodo del clock. In forma semplificata Tcq_min + Tdata_min ≥ Thold + capture_latency − launch_latency + uncertainty, con OCV early/late applicato in senso pessimista. Peggiora spesso a corner fast, alta V e bassa temperatura e viene corretto inserendo delay cell o buffer sul data path, mai abbassando semplicemente la frequenza. Un fix hold deve essere verificato in tutti i corner perché aggiunge delay a setup, e lock-up latch risolve specifici stitch scan inter-domain ma non ogni violazione funzionale.",
    "A hold check requires old data to remain stable for at least t_hold after the same capture edge, making it a minimum-contamination constraint independent of clock period. In simplified form Tcq_min + Tdata_min ≥ Thold + capture_latency − launch_latency + uncertainty, with early and late OCV applied pessimistically. It often worsens at fast process, high voltage, and low temperature and is fixed by inserting delay cells or buffers on the data path, never merely by lowering frequency. A hold fix must be checked at every corner because it consumes setup margin, and a lock-up latch solves specific inter-domain scan stitches rather than every functional violation."
  ),
  MMMC: loc(
    "Multi-Mode Multi-Corner organizza l'analisi simultanea di mode funzionale, scan shift/capture, MBIST, sleep o DVFS contro corner PVT e RC differenti. Ogni scenario combina constraint mode, Liberty operating condition, parasitic corner, derate e power state; dieci mode per dodici corner possono creare 120 viste prima del pruning. P&R usa scenario attivi per ottimizzazione concorrente, mentre PrimeTime o Tempus verifica la matrice signoff e identifica corner dominanti per setup, hold, SI e DRV. MMMC non significa provare indiscriminatamente ogni prodotto cartesiano: scenario illegali si eliminano con giustificazione, ma omettere un mode o una voltage state reale lascia un buco di signoff.",
    "Multi-Mode Multi-Corner organizes concurrent analysis of functional, scan shift/capture, MBIST, sleep, or DVFS modes against different PVT and RC corners. Each scenario combines mode constraints, a Liberty operating condition, a parasitic corner, derates, and a power state; ten modes by twelve corners can create 120 views before pruning. P&R uses active scenarios for concurrent optimization, while PrimeTime or Tempus verifies the signoff matrix and identifies dominant setup, hold, SI, and DRV corners. MMMC does not mean blindly analyzing every Cartesian product: impossible scenarios may be removed with justification, but omitting a real mode or voltage state leaves a signoff hole."
  ),
  OCV: loc(
    "On-Chip Variation modella differenze locali di processo, tensione e temperatura tra celle che un singolo corner globale non rappresenta. Il metodo flat applica derate early e late, per esempio 0,95× e 1,05×, scegliendo combinazioni pessimiste su data e clock per setup o hold. È semplice ma sovrastima path lunghi e common path perché assume variazioni estreme e correlate in modo avverso, rendendo necessario CPPR e spesso margine eccessivo. AOCV aggiunge dipendenza da depth/distance e POCV usa sigma per cella, ma OCV flat resta utile in fasi early o nodi meno avanzati quando le viste qualificate lo prescrivono.",
    "On-Chip Variation models local process, voltage, and temperature differences among cells that a single global corner cannot represent. The flat method applies early and late derates, for example 0.95× and 1.05×, choosing pessimistic data and clock combinations for setup or hold. It is simple but overstates long and common paths by assuming adversarial extreme variation, making CPPR and often excessive margin necessary. AOCV adds depth and distance dependence and POCV uses per-cell sigma, but flat OCV remains useful in early stages or mature nodes when qualified views prescribe it."
  ),
  AOCV: loc(
    "Advanced On-Chip Variation sostituisce i derate flat con tabelle indicizzate per path depth e spesso distanza fisica. Molti stadi tendono a mediare variazioni casuali, quindi il derate di un path profondo è normalmente meno pessimista di quello di un path a uno o due stadi. STA deve associare correttamente launch/capture, bounding box, clock e data alle tabelle foundry, con CPPR per la porzione clock comune. AOCV è deterministico e table-based, distinto da POCV/LVF che propaga media e sigma; è un ponte pratico quando il nodo o la library non dispone di characterization statistica completa.",
    "Advanced On-Chip Variation replaces flat derates with tables indexed by path depth and often physical distance. Many stages tend to average random variation, so a deep path normally receives a less pessimistic derate than a one- or two-stage path. STA must map launch/capture, bounding boxes, clock, and data to the foundry tables correctly, with CPPR for the common clock portion. AOCV is deterministic and table-based, unlike POCV/LVF propagation of mean and sigma; it is a practical bridge when a node or library lacks full statistical characterization."
  ),
  POCV: loc(
    "Parametric On-Chip Variation rappresenta delay di cella e net come distribuzioni e propaga sensibilità statistiche invece di usare un unico derate discreto. Liberty Variation Format fornisce sigma, mean shift e talvolta momenti dipendenti da slew/load, consentendo report a 3σ o 4σ secondo il criterio di yield. Correlation, spatial component, path sigma e sigma scaling devono seguire il methodology deck, altrimenti il numero di deviazioni standard non corrisponde al rischio silicon atteso. POCV è più granulare di AOCV ma non elimina corner PVT, SI o IR-aware STA: la variazione locale si combina ancora con condizioni globali e parassiti.",
    "Parametric On-Chip Variation represents cell and net delays as distributions and propagates statistical sensitivities instead of applying one discrete derate. Liberty Variation Format supplies sigma, mean shift, and sometimes slew/load-dependent moments, enabling reports at 3σ or 4σ according to the yield criterion. Correlation, spatial components, path sigma, and sigma scaling must follow the methodology deck or the reported standard-deviation multiple will not match expected silicon risk. POCV is more granular than AOCV but does not remove PVT corners, SI, or IR-aware STA: local variation still combines with global conditions and parasitics."
  ),
  CPPR: loc(
    "Clock Path Pessimism Removal restituisce il pessimismo introdotto quando lo stesso segmento clock comune è trattato early sul launch e late sul capture, o viceversa. Se un buffer comune riceve 95 ps early e 105 ps late, fino a 10 ps non possono coesistere fisicamente sullo stesso evento e vengono accreditati allo slack secondo le regole del tool. Il calcolo dipende dal punto di divergenza, edge, waveform, OCV/AOCV/POCV e compatibilità delle clock path, quindi report_clock_timing e dettaglio CRPR devono essere auditabili. CPPR è il concetto generale sul common path; CRPR enfatizza il caso di clock che divergono e riconvergono, ma entrambi rimuovono solo pessimismo, non una violazione reale.",
    "Clock Path Pessimism Removal returns pessimism introduced when the same common clock segment is treated early on launch and late on capture, or vice versa. If a common buffer is assigned 95 ps early and 105 ps late, up to 10 ps cannot physically coexist for the same event and is credited back to slack under tool rules. The calculation depends on divergence point, edge, waveform, OCV/AOCV/POCV, and clock-path compatibility, so report_clock_timing and detailed CRPR values must be auditable. CPPR is the general common-path concept; CRPR emphasizes clocks that diverge and reconverge, but both remove only pessimism rather than a real violation."
  ),
  SI: loc(
    "Signal Integrity nel digital signoff studia come accoppiamento, rumore di alimentazione e interconnessioni alterino delay o livello logico di una net. STA SI-aware allinea finestre di switching aggressor-victim e calcola delta delay: aggressor opposto può rallentare la victim, mentre commutazione concorde può accelerarla e danneggiare hold. PrimeTime SI, Tempus e extraction coupled SPEF verificano crosstalk delay, glitch noise, double-switching e spesso limiti noise Liberty su tutti i corner rilevanti. SI non coincide con timing nominale né con package SI analogica; shielding, spacing, NDR, layer change o buffering correggono coupling on-chip a costo di area e capacità.",
    "Signal Integrity in digital signoff studies how coupling, supply noise, and interconnect alter a net's delay or logic level. SI-aware STA aligns aggressor and victim switching windows and computes delta delay: opposite switching can slow the victim, while same-direction switching can speed it up and hurt hold. PrimeTime SI, Tempus, and coupled-SPEF extraction check crosstalk delay, glitch noise, double switching, and often Liberty noise limits across relevant corners. SI is neither nominal timing nor analog package SI; shielding, spacing, NDRs, layer changes, or buffering fix on-chip coupling at an area and capacitance cost."
  ),
  Crosstalk: loc(
    "Crosstalk è l'interazione tra net vicine attraverso capacitance di coupling Cc, particolarmente forte su tratti lunghi paralleli e layer con pitch stretto. Il rapporto Cc/Ctotal e la direzione relativa degli aggressor modificano slew e delay della victim; un aggressor quieto può anche ricevere un glitch capace di superare la noise margin. Extraction coupled e STA SI usano finestre temporali per evitare di sommare aggressor che non possono commutare insieme, ma mode o activity errati producono ottimismo o pessimismo. Aumentare spacing, cambiare layer, accorciare parallel run, schermare con VSS o inserire buffer riduce crosstalk, mentre un semplice fix setup può spostare il problema su hold.",
    "Crosstalk is interaction between nearby nets through coupling capacitance Cc, especially over long parallel runs on tightly pitched layers. The Cc/Ctotal ratio and relative aggressor direction change victim slew and delay; an otherwise quiet victim can also receive a glitch exceeding its noise margin. Coupled extraction and SI STA use timing windows to avoid summing aggressors that cannot switch together, but incorrect modes or activity create optimism or pessimism. Increasing spacing, changing layers, shortening parallel runs, shielding with VSS, or inserting buffers reduces crosstalk, while a simple setup fix may move the problem to hold."
  ),
  DRV: loc(
    "Design Rule Violations in timing implementation sono violazioni elettriche di max_transition, max_capacitance o max_fanout dichiarate in Liberty o nella metodologia. Non sono slack: una net può rispettare setup ma avere slew 180 ps contro un limite 120 ps, costringendo il tool a estrapolare tabelle e rendendo delay, power e affidabilità non qualificati. Buffering, driver upsizing, fanout replication o route improvement correggono il carico, ma possono aumentare area, leakage, congestion e hold debt. Il signoff richiede tipicamente zero DRV prima di fidarsi di WNS/TNS; DRC geometrico foundry è un controllo differente nonostante l'acronimo simile.",
    "Design Rule Violations in timing implementation are electrical violations of max_transition, max_capacitance, or max_fanout declared by Liberty or methodology constraints. They are not slack: a net may meet setup yet show 180 ps slew against a 120 ps limit, forcing table extrapolation and making delay, power, and reliability unqualified. Buffering, driver upsizing, fanout replication, or routing improvement fixes the load but can increase area, leakage, congestion, and hold debt. Signoff typically requires zero DRVs before WNS/TNS is trusted; foundry geometric DRC is a different check despite the similar acronym."
  ),
  "False Path": loc(
    "Un false path è un percorso presente nel timing graph ma impossibile da sensibilizzare in qualsiasi funzionamento legale, quindi viene escluso con set_false_path. Esempi validi includono crossing asincroni trattati da protocollo o logica mutuamente esclusiva provata, ma il constraint deve specificare from, through e to con precisione e avere una giustificazione funzionale. Una wildcard troppo ampia può nascondere un path reale e produrre silicon failure anche con STA verde, perciò lint SDC, formal reachability e review delle eccezioni sono gate di signoff. Un path lento ma raro non è false: se può attivarsi deve essere temporizzato, eventualmente come multicycle con relazione di ciclo dimostrata.",
    "A false path exists in the timing graph but cannot be sensitized in any legal operation, so set_false_path excludes it from analysis. Valid examples include protocol-managed asynchronous crossings or proven mutually exclusive logic, but the constraint must target from, through, and to objects precisely and carry a functional justification. An overly broad wildcard can hide a real path and cause silicon failure despite green STA, so SDC lint, formal reachability, and exception review are signoff gates. A slow but rare path is not false: if it can activate it must be timed, possibly as multicycle when its cycle relationship is proven."
  ),
  "Multicycle Path": loc(
    "Un multicycle path è funzionalmente autorizzato a usare N cicli tra launch e capture e viene modellato con set_multicycle_path, non escluso dall'analisi. Per un path setup N, la relazione hold va impostata deliberatamente, spesso N−1 rispetto allo spostamento setup nella semantica SDC, per non introdurre un check hold involontariamente severo o permissivo. Enable, protocollo o FSM devono garantire che il receiver non campioni prima, idealmente con assertion o formal, e from/to devono evitare collezioni troppo larghe. A differenza del false path il path resta temporizzato con budget esteso; dimenticare il constraint hold associato è una causa classica di timing closure falsa.",
    "A multicycle path is functionally allowed to use N cycles between launch and capture and is modeled with set_multicycle_path rather than excluded. For an N-cycle setup path, the hold relationship must be set deliberately, often N−1 relative to the setup shift under SDC semantics, to avoid an unintentionally strict or permissive hold check. An enable, protocol, or FSM must guarantee that the receiver does not sample earlier, ideally through assertions or formal proof, and from/to collections must avoid broad matching. Unlike a false path, the path remains timed with an extended budget; omitting the companion hold constraint is a classic source of false closure."
  ),
  "Generated Clock": loc(
    "Un generated clock è un clock derivato da un master tramite divider, mux, PLL, gate o altra logica e deve essere dichiarato con create_generated_clock sul pin sorgente corretto. Divide_by, multiply_by, edges, inversion e phase mantengono la relazione con il master, permettendo STA di analizzare crossing sincroni, propagated latency e waveform reali. Definire un nuovo create_clock indipendente sul punto derivato perde relazione di fase e può creare false asynchronous path o margine errato. CTS e signoff devono includere ogni root e mode di mux, con clock exclusivity e case analysis coerenti per evitare doppio conteggio o path unconstrained.",
    "A generated clock is derived from a master through a divider, mux, PLL, gate, or other logic and must be declared with create_generated_clock on the correct source pin. Divide_by, multiply_by, edges, inversion, and phase preserve its master relationship so STA can analyze synchronous crossings, propagated latency, and real waveforms. Declaring an unrelated create_clock at the derived point loses phase relationships and can create false asynchronous paths or wrong margin. CTS and signoff must include every root and mux mode, with coherent clock exclusivity and case analysis to avoid double counting or unconstrained paths."
  ),
  "Useful Skew": loc(
    "Useful skew modifica intenzionalmente il tempo di arrivo clock relativo tra launch e capture per trasferire margine da un path a un altro. Ritardare il capture aiuta setup ma tende a peggiorare hold sullo stesso arco, quindi l'ottimizzazione CTS deve valutare contemporaneamente tutti i fanin/fanout e gli scenario MMMC. Un esempio di +30 ps può recuperare 30 ps setup idealmente, ma uncertainty, OCV, shared path e discreti buffer riducono il guadagno reale e aumentano latency o power. Non è una waiver né clock uncertainty negativa: il tree fisico implementa lo skew e STA propagated-clock deve verificarlo post-route.",
    "Useful skew intentionally changes relative launch and capture clock arrival to transfer margin from one path to another. Delaying capture helps setup but tends to hurt hold on that arc, so CTS optimization must evaluate all fanin, fanout, and MMMC scenarios concurrently. A +30 ps change can ideally recover 30 ps of setup, but uncertainty, OCV, shared paths, and discrete buffers reduce the real gain and may increase latency or power. It is neither a waiver nor negative clock uncertainty: the physical tree implements the skew and propagated-clock STA must verify it post-route."
  ),
  "Clock Uncertainty": loc(
    "Clock uncertainty è il margine SDC sottratto al budget per rappresentare jitter, phase error, modellazione incompleta e riserva di progetto. Pre-CTS può includere skew atteso oltre al jitter, per esempio 100–200 ps, mentre post-CTS lo skew è propagato dal tree e l'incertezza viene ridotta ai componenti non già modellati, spesso 30–100 ps secondo spec. Setup e hold possono avere valori differenti e rise/fall o inter-clock uncertainty devono riflettere PLL, duty-cycle distortion e correlazione. Sommare uncertainty, OCV e margin già presenti in Liberty senza decomposition crea doppio pessimismo; eliminarla per chiudere WNS nasconde rischio reale.",
    "Clock uncertainty is SDC margin removed from timing budget to represent jitter, phase error, incomplete modeling, and design reserve. Before CTS it may include expected skew in addition to jitter, for example 100–200 ps, while after CTS propagated skew comes from the tree and uncertainty is reduced to components not already modeled, often 30–100 ps by specification. Setup and hold can use different values, and rise/fall or inter-clock uncertainty must reflect PLL behavior, duty-cycle distortion, and correlation. Stacking uncertainty, OCV, and margin already embedded in Liberty creates double pessimism; deleting it to close WNS hides real risk."
  ),
  PEX: loc(
    "Parasitic Extraction converte la geometria routed in reti di resistance e capacitance, inclusa coupling tra conduttori, usando stack e dielectric del PDK. StarRC, Quantus, Calibre xACT o Raphael producono SPEF/DSPF per corner come Cbest/Cworst e RCbest/RCworst, spesso con temperature-dependent resistance. In fasi early si usa global-route estimate o C-only, ma signoff richiede layout finale con fill, via e coupling e una extraction-vs-reference qualification entro tolleranza foundry. PEX non è LVS: LVS prova connettività e device equivalence, mentre extraction quantifica gli elementi parassiti che dominano delay, SI e talvolta IR.",
    "Parasitic Extraction converts routed geometry into resistance and capacitance networks, including conductor-to-conductor coupling, using the PDK stack and dielectrics. StarRC, Quantus, Calibre xACT, or Raphael produces SPEF/DSPF for corners such as Cbest/Cworst and RCbest/RCworst, often with temperature-dependent resistance. Early stages use global-route estimates or capacitance-only models, but signoff requires final layout with fill, vias, and coupling plus extraction-to-reference qualification within foundry tolerance. PEX is not LVS: LVS proves connectivity and device equivalence, while extraction quantifies parasitic elements that dominate delay, SI, and sometimes IR."
  ),
  "NLDM vs CCS": loc(
    "NLDM modella delay e output slew con tabelle bidimensionali indicizzate da input slew e effective load, assumendo una forma d'onda implicita. Composite Current Source descrive invece correnti e waveform dipendenti dal tempo, receiver capacitance e noise, catturando meglio driver deboli, Miller coupling, waveform non monotone e SI ai nodi avanzati. CCS richiede più dati e runtime ma riduce errore rispetto a SPICE quando interconnect e slew escono dalle condizioni semplici; ECSM è un'alternativa current-source analoga. Entrambi vivono in Liberty e dipendono dalla characterization range: nessun modello è affidabile se max slew/load viene violato o il corner non corrisponde.",
    "NLDM models delay and output slew with two-dimensional tables indexed by input slew and effective load, assuming an implicit waveform shape. Composite Current Source instead describes time-dependent currents and waveforms, receiver capacitance, and noise, better capturing weak drivers, Miller coupling, nonmonotonic waveforms, and SI at advanced nodes. CCS requires more data and runtime but reduces error against SPICE when interconnect and slew leave simple conditions; ECSM is a comparable current-source alternative. Both reside in Liberty and depend on characterization range: neither model is trustworthy when maximum slew or load is violated or the corner does not match."
  ),
  "IR-aware STA": loc(
    "IR-aware STA annota a ogni istanza la tensione locale ottenuta da un'analisi static o dynamic IR invece di assumere VDD uniforme per tutto il die. Il delay cresce quando Vlocale cala, spesso in modo non lineare vicino a low-V operation, quindi un path che aveva +20 ps può diventare negativo se attraversa un hotspot di droop. RedHawk-SC, Voltus e PrimeTime/Tempus scambiano voltage map o derate e devono allineare activity window, power state, PVT, placement e timestamp. Non sostituisce IR signoff né MMMC: collega il failure elettrico alla conseguenza timing e evita sia corner uniforme eccessivamente pessimista sia ottimismo sui hotspot.",
    "IR-aware STA annotates each instance with local voltage from static or dynamic IR analysis instead of assuming a uniform VDD across the die. Delay increases as local voltage falls, often nonlinearly near low-voltage operation, so a path with +20 ps can become negative when it crosses a droop hotspot. RedHawk-SC, Voltus, and PrimeTime or Tempus exchange voltage maps or derates and must align activity windows, power states, PVT, placement, and timestamps. It replaces neither IR signoff nor MMMC: it connects an electrical failure to its timing consequence while avoiding both an overly pessimistic uniform corner and optimism at hotspots."
  ),

  // Physical design and routing
  Floorplan: loc(
    "Il floorplan definisce die/core boundary, aspect ratio, macro e IO placement, channel, voltage island, blockage e scheletro PDN prima del placement standard-cell. Decide gran parte del PPA perché distanza macro-pin, larghezza dei canali e accesso ai bump determinano wirelength, congestion, latency e IR che ottimizzazioni locali non recuperano. Un piano industriale usa stime di area e utilization, flyline/net-weight, pin density, keepout e early global route, lasciando margine per CTS, hold buffer, decap e ECO. Non è un disegno estetico né placement finale: deve superare legality, PG connectivity, macro orientation, package alignment e floorplan-exit review con dati quantitativi.",
    "Floorplanning defines die and core boundaries, aspect ratio, macro and I/O placement, channels, voltage islands, blockages, and the PDN skeleton before standard-cell placement. It determines much of PPA because macro-to-pin distance, channel width, and bump access set wirelength, congestion, latency, and IR that local optimization cannot recover. An industrial plan uses area and utilization estimates, flylines or net weights, pin density, keepouts, and early global routing while reserving margin for CTS, hold buffers, decaps, and ECOs. It is neither an aesthetic drawing nor final placement: it must pass legality, power connectivity, macro orientation, package alignment, and quantitative floorplan-exit review."
  ),
  Utilization: loc(
    "Utilization misura l'area occupata dalle celle placeable rispetto all'area effettivamente disponibile nel core, con formule che devono dichiarare se macro, blockage e halo sono inclusi. Un valore globale del 70% può nascondere bin locali oltre il 100%, quindi placement usa density map e target regionali, spesso 60–80% secondo nodo e complessità. Valori troppo alti lasciano insufficienti site e track per buffering CTS, hold fix, decap e riparazioni DRC, causando displacement, congestion e route failure. Valori troppo bassi aumentano die cost, wirelength, clock power e leakage del tree; utilization non è la stessa cosa di routing utilization o GRC.",
    "Utilization measures placeable cell area against effectively available core area, with formulas that must state whether macros, blockages, and halos are included. A global 70% value can hide local bins above 100%, so placement uses density maps and regional targets, often 60–80% depending on node and complexity. Excess utilization leaves too few sites and tracks for CTS buffering, hold fixes, decaps, and DRC repair, causing displacement, congestion, and routing failure. Too little utilization increases die cost, wirelength, clock power, and tree leakage; placement utilization is not routing utilization or GRC."
  ),
  "Halo / Keepout": loc(
    "Un halo o keepout è un margine attorno a macro, boundary o cella nel quale il placer vieta o limita altre istanze. Protegge pin access, notch stretti, power ring, routing escape e regioni dove la densità locale renderebbe impossibile detailed route, con margini spesso diversi sui quattro lati. Hard keepout proibisce placement, soft o partial keepout consente alcune classi o percentuali e può essere rilassato durante optimization secondo la metodologia. Non è un routing blockage: quest'ultimo vieta specifici layer o net al router, mentre un halo di placement da solo non impedisce ai wire di attraversare la regione.",
    "A halo or keepout is a margin around a macro, boundary, or cell in which the placer forbids or limits other instances. It protects pin access, narrow notches, power rings, routing escape, and regions where local density would make detailed routing impossible, often with different margins on each side. A hard keepout prohibits placement, while a soft or partial keepout permits selected classes or percentages and may be relaxed during optimization by methodology. It is not a routing blockage: the latter forbids specified layers or nets to the router, whereas a placement halo alone does not stop wires crossing the region."
  ),
  Blockage: loc(
    "Una blockage è una regione geometrica che riduce o annulla risorse di placement o routing per proteggere macro, analog, canali, pin e aree riservate. Placement blockage può essere hard, soft o partial con percentuale di density, mentre routing blockage seleziona layer, direzione, via o tipo di net. L'uso corretto guida congestion e integrità, ma blockage eccessive spostano domanda sui bordi e possono creare hotspot, wire detour o impossibilità di chiudere PG e clock. Halo e region sono concetti correlati ma diversi: l'halo segue un oggetto, la region assegna celle, e la blockage sottrae capacità fisica.",
    "A blockage is a geometric region that reduces or removes placement or routing resources to protect macros, analog areas, channels, pins, and reserved space. Placement blockages may be hard, soft, or partial with a density percentage, while routing blockages select layers, directions, vias, or net types. Correct use guides congestion and integrity, but excessive blockages push demand to edges and can create hotspots, wire detours, or inability to close power and clock routing. Halos and regions are related but different: a halo follows an object, a region assigns cells, and a blockage subtracts physical capacity."
  ),
  CTS: loc(
    "Clock Tree Synthesis costruisce una rete di buffer, inverter, gate e route dal clock root a migliaia o milioni di sink rispettando skew, latency, transition, duty cycle e power. Usa celle clock caratterizzate, NDR, shielding e topology constraints, bilanciando local skew utile per setup/hold e global insertion delay in tutti gli scenario. Dopo CTS i clock diventano propagated e STA vede latency fisica; optimization inserisce hold buffer e corregge gating check, pulse width, DRV e reconvergence. CTS non è HFNS: reset e scan_enable richiedono fanout control ma non la stessa accuratezza di edge, skew e jitter di una rete clock.",
    "Clock Tree Synthesis builds a network of buffers, inverters, gates, and routes from a clock root to thousands or millions of sinks while meeting skew, latency, transition, duty-cycle, and power targets. It uses characterized clock cells, NDRs, shielding, and topology constraints, balancing useful local skew for setup/hold with global insertion delay across scenarios. After CTS clocks become propagated and STA sees physical latency; optimization inserts hold buffers and fixes gating checks, pulse width, DRVs, and reconvergence. CTS is not HFNS: reset and scan-enable need fanout control but not the same edge, skew, and jitter precision as a clock network."
  ),
  "Clock Mesh": loc(
    "Una clock mesh distribuisce il clock su una griglia metallica ridondante alimentata da molti driver, riducendo sensibilità a variation e differenze di path. Può ottenere local skew nell'ordine di 5–20 ps per CPU/GPU multi-GHz, ma l'elevata capacitance commuta ogni ciclo e costa spesso 2–3× la power di un tree. Mesh pitch, tap, driver phase, EM, resonant behavior e coupling richiedono co-ottimizzazione e routing su layer alti con risorse sostanziali. A differenza di un tree, molteplici cammini elettrici raggiungono ogni sink, rendendo extraction e simulation della rete più complesse ma più robuste a OCV.",
    "A clock mesh distributes the clock over a redundant metal grid driven at many points, reducing sensitivity to variation and path differences. It can achieve roughly 5–20 ps local skew in multi-GHz CPUs or GPUs, but its large capacitance switches every cycle and often costs 2–3× the power of a tree. Mesh pitch, taps, driver phase, EM, resonant behavior, and coupling require co-optimization and substantial upper-metal routing resources. Unlike a tree, multiple electrical paths reach each sink, making extraction and network simulation more complex but more robust against OCV."
  ),
  Skew: loc(
    "Clock skew è la differenza t_capture_clock − t_launch_clock tra tempi di arrivo di due sink per edge correlati. Positive skew può aiutare setup e danneggiare hold, negative skew l'opposto, ma la conseguenza dipende dalla convenzione e dal path specifico. Global skew confronta estremi dell'intero dominio, mentre local skew launch-capture è la metrica direttamente rilevante allo slack e include propagated route, OCV e CPPR. CTS non deve minimizzare ciecamente ogni skew a zero: useful skew può migliorare closure, purché pulse width, latency e tutti i corner restino firmati.",
    "Clock skew is the difference t_capture_clock − t_launch_clock between arrival times at two sinks for related edges. Positive skew can help setup and hurt hold, with negative skew doing the opposite, although the consequence depends on convention and the specific path. Global skew compares extremes across a domain, while launch-to-capture local skew is directly relevant to slack and includes propagated routes, OCV, and CPPR. CTS should not blindly force every skew to zero: useful skew can improve closure provided pulse width, latency, and every corner remain signed off."
  ),
  Latency: loc(
    "Clock latency è il tempo dal clock source definito al sink, separato in source latency esterna e network o insertion latency on-chip. Prima di CTS viene stimato con set_clock_latency; dopo CTS la route propagata fornisce delay reale che può raggiungere centinaia di picosecondi o più in SoC grandi. Latency assoluta influenza I/O timing, relazione con macro/PLL, power e numero di buffer, mentre lo skew è la differenza tra due latency e può restare piccolo anche se entrambe sono grandi. Report e SDC devono evitare di sommare latency ideale e propagated, una doppia modellazione che sposta required time e nasconde errori d'interfaccia.",
    "Clock latency is the time from a defined clock source to a sink, separated into external source latency and on-chip network or insertion latency. Before CTS it is estimated with set_clock_latency; after CTS the propagated route supplies real delay that may reach hundreds of picoseconds or more in large SoCs. Absolute latency affects I/O timing, macro or PLL relationships, power, and buffer count, while skew is the difference between two latencies and may remain small even when both are large. Reports and SDC must avoid adding ideal and propagated latency together, a double model that shifts required times and hides interface errors."
  ),
  Legalization: loc(
    "Legalization sposta le celle dalla soluzione continua del global placer a coordinate SITE e ROW valide senza overlap e con orientamento consentito. Deve rispettare fixed macro, region, fence, halo, voltage area, multi-height row, rail alignment e spazi per tap/endcap, minimizzando displacement e wirelength degradation. Detailed placement successivo ottimizza swap, reorder e local density, ma una legalization con grandi spostamenti segnala utilization o blockage incompatibili col floorplan. Essere legal non significa routeable o DRC-clean: pin access, implant spacing e congestion richiedono ulteriori controlli e placement refinement.",
    "Legalization moves cells from the global placer's continuous solution onto valid SITE and ROW coordinates without overlap and with permitted orientations. It must honor fixed macros, regions, fences, halos, voltage areas, multi-height rows, rail alignment, and tap/endcap space while minimizing displacement and wirelength degradation. Detailed placement later optimizes swaps, reordering, and local density, but legalization with large movement signals utilization or blockage incompatible with the floorplan. Legal placement is not necessarily routable or DRC-clean: pin access, implant spacing, and congestion require additional checks and refinement."
  ),
  Congestion: loc(
    "Congestion si verifica quando la domanda stimata o reale di wire e via in un GCell supera la capacità disponibile dei track, spesso espressa come overflow = demand − capacity. Hotspot sopra pochi punti percentuali dopo placement o global route predicono detour, DRC, timing degradation e route failure, anche se l'utilization globale sembra moderata. Pin density, macro channel, blockage, high-fanout net e layer reservation sono cause comuni; rimedi includono cell spreading, macro movement, buffering topology, layer adjustment e logic restructuring. Congestion non è semplicemente density: un'area poco occupata può essere congestionata da attraversamenti, mentre GRC quantifica la pressione di global routing.",
    "Congestion occurs when estimated or actual wire and via demand in a GCell exceeds available track capacity, often expressed as overflow = demand − capacity. Hotspots above a few percent after placement or global routing predict detours, DRCs, timing degradation, and routing failure even when global utilization appears moderate. Pin density, macro channels, blockages, high-fanout nets, and layer reservations are common causes; remedies include cell spreading, macro movement, topology changes, layer adjustment, and logic restructuring. Congestion is not merely density: a lightly occupied area can be congested by crossings, while GRC quantifies global-routing pressure."
  ),
  ECO: loc(
    "Engineering Change Order è una modifica controllata dopo una baseline, usata per correggere funzione, timing, power, DRC o test senza rifare necessariamente l'intero flusso. Un functional ECO cambia logica e richiede LEC, STA e spesso ATPG regeneration, mentre un physical ECO usa sizing, buffer, route o spare cell mantenendo funzione equivalente. Dopo BTO un metal-only ECO può riconnettere spare gate senza cambiare FEOL, ma dopo MTO qualsiasi geometria mask richiede respin e costo elevato. Ogni ECO deve essere tracciato, implementato su netlist e layout coerenti e riverificato incrementalmente più regression sui check impattati, perché fix locali possono creare hold, SI, EM o LVS failure.",
    "An Engineering Change Order is a controlled modification after a baseline, used to fix function, timing, power, DRC, or test without necessarily rerunning the entire flow. A functional ECO changes logic and requires LEC, STA, and often ATPG regeneration, while a physical ECO uses sizing, buffers, routing, or spare cells while preserving equivalent function. After BTO, a metal-only ECO can reconnect spare gates without changing FEOL, but after MTO any mask geometry change requires an expensive respin. Every ECO must be tracked, applied to coherent netlist and layout views, and reverified incrementally plus regression on impacted checks because local fixes can create hold, SI, EM, or LVS failures."
  ),
  "P&R": loc(
    "Place and Route trasforma una netlist e i suoi constraint in un layout implementabile attraverso floorplan, placement, optimization, CTS, routing e finishing. Innovus, ICC2 e Aprisa ottimizzano PPA e closure MMMC usando LEF/DEF, Liberty, SDC, UPF e RC technology, poi producono netlist post-route, DEF e GDS/OASIS. Milestone intermedi controllano legality, congestion, timing, DRV, PG connectivity, antenna e route DRC prima del signoff indipendente con STA, PV e power tools. P&R non è tapeout signoff da solo: il database del tool può essere internamente clean ma fallire extraction, Calibre DRC/LVS o IR/EM con deck foundry finale.",
    "Place and Route transforms a netlist and constraints into implementable layout through floorplanning, placement, optimization, CTS, routing, and finishing. Innovus, ICC2, and Aprisa optimize PPA and MMMC closure using LEF/DEF, Liberty, SDC, UPF, and RC technology, then produce a post-route netlist, DEF, and GDS/OASIS. Intermediate milestones check legality, congestion, timing, DRVs, power connectivity, antenna, and routing DRC before independent STA, PV, and power signoff. P&R alone is not tapeout signoff: the implementation database may be internally clean yet fail extraction, final-foundry Calibre DRC/LVS, or IR/EM."
  ),
  FF: loc(
    "Un flip-flop è un elemento sequenziale edge-triggered che campiona D sul fronte di clock e presenta Q dopo clock-to-Q, con constraint setup, hold, recovery/removal e pulse width caratterizzati in Liberty. Varianti includono reset/set sync o async, enable, multi-bit FF, retention e SDFF, ciascuna con area, pin, power e archi differenti. Milioni di FF dominano sink CTS e clock dynamic power, quindi multi-bit banking e clock gating riducono capacitance ma complicano placement, scan e ECO. Un FF non è un latch level-sensitive: la distinzione cambia borrowing, timing graph e rischio di transparency, e non deve essere nascosta da RTL ambiguo.",
    "A flip-flop is an edge-triggered sequential element that samples D on a clock edge and presents Q after clock-to-Q, with setup, hold, recovery/removal, and pulse-width constraints characterized in Liberty. Variants include synchronous or asynchronous reset/set, enable, multi-bit FFs, retention, and SDFFs, each with different area, pins, power, and arcs. Millions of FFs dominate CTS sinks and clock dynamic power, so multi-bit banking and clock gating reduce capacitance while complicating placement, scan, and ECOs. A flip-flop is not a level-sensitive latch: the distinction changes borrowing, timing graphs, and transparency risk and must not be obscured by ambiguous RTL."
  ),
  "Std Cell": loc(
    "Una standard cell è un blocco digitale pre-progettato come inverter, NAND, mux, buffer o flip-flop, con altezza compatibile alle row e larghezza quantizzata al SITE. Il PDK/library fornisce viste coerenti Liberty per timing/power, LEF per abstract layout, GDS/CDL per PV e Verilog per function, spesso in drive strength e Vt multipli. Synthesis sceglie funzione e size, mentre placement/legalization rispetta rail, well, implant e pin access e optimization esegue swap per PPA. A differenza di una macro SRAM o analog, la std cell viene collocata in massa e instradata su rail condivisi, ma incoerenze tra viste causano LEC, DRC o LVS failure.",
    "A standard cell is a predesigned digital block such as an inverter, NAND, mux, buffer, or flip-flop, with row-compatible height and SITE-quantized width. The PDK or library supplies coherent Liberty timing/power, LEF abstract layout, GDS/CDL physical, and Verilog functional views, often across multiple drive strengths and Vt options. Synthesis selects function and size, while placement and legalization honor rails, wells, implants, and pin access and optimization performs PPA swaps. Unlike an SRAM or analog macro, standard cells are placed in bulk and routed on shared rails, but inconsistent views cause LEC, DRC, or LVS failures."
  ),
  NDR: loc(
    "Una Non-Default Rule modifica width, spacing, via count o layer preference rispetto alle regole minime per classi di net come clock, reset, analog e segnali critici. Una regola 2W2S riduce resistance e coupling e migliora EM/SI, mentre redundant via aumenta current capacity e yield, ma consuma più track e può aggravare congestion. Router e CTS devono applicarla end-to-end incluse via transition e verificare eccezioni o segmenti non conformi nel database finale. NDR non significa automaticamente shielding né timing migliore: maggiore width riduce R ma aumenta capacitance laterale, e l'effetto va estratto e firmato.",
    "A Non-Default Rule changes width, spacing, via count, or layer preference from minimum rules for net classes such as clocks, resets, analog signals, and critical paths. A 2W2S rule reduces resistance and coupling and improves EM/SI, while redundant vias increase current capacity and yield, but both consume more tracks and can worsen congestion. Routers and CTS must apply it end to end, including via transitions, and check exceptions or nonconforming segments in the final database. An NDR does not automatically imply shielding or better timing: extra width lowers resistance but raises lateral capacitance, so the result must be extracted and signed off."
  ),
  "Preferred Direction": loc(
    "Ogni routing layer ha una direzione preferita, tipicamente alternata orizzontale e verticale, definita da track grid, pitch e regole del technology LEF. Seguirla riduce jog, via, coupling irregolare e pattern lithography complessi, migliorando capacità e prevedibilità del global router. Detailed route può usare segmenti non-preferred per pin access o riparazione, ma spesso richiede width/spacing aggiuntivi e aumenta resistance, DRC risk e via count. Preferred direction non è un divieto assoluto salvo regola foundry specifica; il signoff giudica le geometrie effettive, non l'intenzione del router.",
    "Each routing layer has a preferred direction, typically alternating horizontal and vertical, defined by the track grid, pitch, and technology LEF rules. Following it reduces jogs, vias, irregular coupling, and complex lithography patterns, improving capacity and global-router predictability. Detailed routing may use nonpreferred segments for pin access or repair, but these often require extra width or spacing and increase resistance, DRC risk, and via count. Preferred direction is not an absolute prohibition unless a foundry rule says so; signoff judges actual geometry rather than router intent."
  ),
  "Via Ladder": loc(
    "Una via ladder è una sequenza di via e brevi segmenti che porta una net tra più livelli metal, per esempio M1→M2→M3→M4. Ogni transition aggiunge contact resistance ed enclosure area e deve rispettare cut spacing, via-to-via, min-area e patterning rule; stack troppo alto può essere vietato. Per PG o net ad alta corrente si usano via array e redundant cut verificati con limiti EM per evitare che un singolo via diventi il collo di bottiglia. Non è solo un oggetto geometrico innocuo: ladder eccessive aumentano delay, DRC e pin-access congestion, mentre una via mancante produce open in LVS.",
    "A via ladder is a sequence of vias and short segments that moves a net across several metal levels, for example M1→M2→M3→M4. Each transition adds contact resistance and enclosure area and must satisfy cut spacing, via-to-via, minimum-area, and patterning rules; very tall stacks may be forbidden. Power or high-current nets use via arrays and redundant cuts checked against EM limits so one via does not become the bottleneck. It is not an electrically harmless shape: excessive ladders increase delay, DRCs, and pin-access congestion, while a missing via creates an LVS open."
  ),
  "Pin Access": loc(
    "Pin access è la capacità del detailed router di raggiungere un pin LEF con almeno una combinazione legale di track, via ed enclosure senza bloccare le net vicine. Celle dense AOI/OAI, mux e multi-height vicino a macro boundary possono avere access point nominali ma nessun pattern DRC-clean dopo abutment. Analisi pre-route conta access point e hotspot, quindi cell padding, orientation swap, spreading o alternate cell architecture prevengono migliaia di search-and-repair iteration. Non equivale a connettività logica: un pin può essere presente nella netlist e nel LEF ma fisicamente irraggiungibile sul pattern di placement scelto.",
    "Pin access is the detailed router's ability to reach a LEF pin through at least one legal track, via, and enclosure combination without blocking neighboring nets. Dense AOI/OAI, mux, and multi-height cells near macro boundaries may expose nominal access points yet have no DRC-clean pattern after abutment. Pre-route analysis counts access points and hotspots, so cell padding, orientation swaps, spreading, or alternate cell architectures prevent thousands of search-and-repair iterations. It is not logical connectivity: a pin can exist in the netlist and LEF yet be physically unreachable in the chosen placement pattern."
  ),
  Track: loc(
    "Un track è una linea discreta della griglia su cui il router centra wire e via, derivata da pitch, offset e direzione di ciascun metal layer. La capacità locale è approssimativamente il numero di track disponibili meno blockage e occupazione PG, ma regole multi-patterning e via enclosure riducono la capacità utilizzabile. A nodi avanzati pin e standard cell sono spesso track-based, per esempio architetture 6T o 7.5T, e un access off-grid può richiedere jog o via speciale. Track non significa net: molti segmenti di net condividono layer diversi, e una singola net larga NDR può consumare più track con spacing.",
    "A track is a discrete grid line on which the router centers wires and vias, derived from each metal layer's pitch, offset, and direction. Local capacity is approximately available track count minus blockages and power occupancy, although multipatterning and via-enclosure rules reduce usable capacity. At advanced nodes pins and standard cells are often track-based, for example 6T or 7.5T architectures, and off-grid access may need jogs or special vias. A track is not a net: one net uses segments on several layers, and a wide NDR net can consume multiple tracks including spacing."
  ),
  "Search & Repair": loc(
    "Search and Repair è la fase iterativa del detailed router che individua violazioni locali e applica rip-up, reroute, wire spreading, via swap o patch geometry. Opera su spacing, short, min-area, enclosure, cut/color e antenna, spesso ordinando i marker per severità e limitando la perturbazione del timing già chiuso. Il conteggio può scendere da milioni a zero ma plateau e marker oscillanti indicano congestione strutturale, pin access impossibile o rule interaction che richiede modifica di placement/floorplan. Non sostituisce il DRC signoff foundry: pulisce il rule engine interno, poi Calibre, ICV o Pegasus sul GDS merged resta l'autorità.",
    "Search and Repair is the iterative detailed-router phase that locates local violations and applies rip-up, rerouting, wire spreading, via swaps, or patch geometry. It handles spacing, shorts, minimum area, enclosure, cut or color, and antenna rules, often prioritizing markers while limiting disturbance to closed timing. Counts may fall from millions to zero, but plateaus and oscillating markers indicate structural congestion, impossible pin access, or rule interactions requiring placement or floorplan changes. It does not replace foundry signoff DRC: it cleans the internal rule engine, after which Calibre, ICV, or Pegasus on merged GDS remains authoritative."
  ),
  "Open / Short": loc(
    "Un open è una discontinuità che separa parti della stessa net, mentre uno short collega geometrie appartenenti a net differenti. Open derivano da via mancanti, shape non sovrapposte o pin non raggiunto; short da spacing collassato, wrong-way route, fill o label/net mapping errato. Connectivity check del router e LVS devono riportare zero entrambi, perché un singolo PG open può lasciare migliaia di celle flottanti e un VDD-VSS short può essere catastrofico. DRC geometrico può trovare molti short ma non sempre comprende la net intent, quindi route check, extraction e LVS sono controlli complementari e non intercambiabili.",
    "An open is a discontinuity separating pieces of the same net, while a short connects geometry belonging to different nets. Opens arise from missing vias, nonoverlapping shapes, or unreached pins; shorts arise from collapsed spacing, wrong-way routes, fill, or incorrect label and net mapping. Router connectivity checks and LVS must report zero of both because one power-grid open can float thousands of cells and a VDD-to-VSS short can be catastrophic. Geometric DRC finds many shorts but does not always understand net intent, so route checks, extraction, and LVS are complementary rather than interchangeable."
  ),
  Antenna: loc(
    "L'effetto antenna è l'accumulo di carica plasma su metallo o gate durante fasi intermedie di etch, quando una lunga area conduttrice scarica attraverso un oxide sottile non ancora protetto. I deck foundry limitano rapporti area o perimeter conductor / gate area per layer e process step, distinti da qualsiasi antenna RF del circuito. Router corregge inserendo diode verso substrate, jumper che porta il segmento a un layer formato più tardi, oppure buffer che divide l'area esposta. Il controllo deve essere zero o waived dalla foundry sul layout finale, perché una net elettricamente corretta in LVS può comunque avere oxide danneggiato e bassa affidabilità.",
    "The antenna effect is plasma-charge accumulation on metal or gate during intermediate etch steps, when a long conductor discharges through thin oxide that is not yet protected. Foundry decks limit conductor-area or perimeter to gate-area ratios by layer and process step, unrelated to any RF antenna in the circuit. Routers fix violations by adding substrate diodes, jumpers that move a segment to a later-formed layer, or buffers that divide exposed area. The final layout must be clean or foundry-waived because a net can be electrically correct in LVS yet suffer oxide damage and poor reliability."
  ),

  // Power delivery and low power
  PDN: loc(
    "La Power Delivery Network è il percorso elettrico completo da VRM e package attraverso bump, RDL, ring, mesh, strap, via stack e rail fino ai pin VDD/VSS di ogni istanza. È progettata da I = P/V e limiti di IR/EM, includendo resistance, package inductance L·di/dt e capacitance distribuita, non soltanto percentuale di area metal. RedHawk-SC, Voltus o Totem verificano static IR, dynamic droop, average/RMS/peak current e via reliability su mode funzionale, scan e BIST. La PDN comprende primary e secondary grid e deve essere LVS/ERC-clean; una griglia larga ma mal connessa può fallire per via bottleneck o island flottante.",
    "The Power Delivery Network is the complete electrical path from VRM and package through bumps, RDL, rings, meshes, straps, via stacks, and rails to every instance's VDD/VSS pins. It is designed from I = P/V and IR/EM limits, including resistance, package inductance L·di/dt, and distributed capacitance rather than only metal-area percentage. RedHawk-SC, Voltus, or Totem checks static IR, dynamic droop, average/RMS/peak current, and via reliability in functional, scan, and BIST modes. The PDN includes primary and secondary grids and must be LVS/ERC-clean; a wide but poorly connected grid can fail through a via bottleneck or floating island."
  ),
  "Primary PG": loc(
    "La Primary Power Grid è il backbone always-on che distribuisce le supply principali dai pad o bump a ring e mesh globali. Alimenta always-on logic, ingressi dei power switch e spesso analog/IO tramite net e constraint separati, dimensionati per corrente aggregata e worst-case EM. Strap pitch, width, layer, via array e bump assignment sono scelti con early IR analysis e raffinati dopo placement/activity, mantenendo continuità attraverso macro channel. È distinta dalla Secondary PG a valle degli switch: confondere VDD e VDD_SW può bypassare power gating o creare short tra domini che LVS/ERC deve rilevare.",
    "The Primary Power Grid is the always-on backbone distributing main supplies from pads or bumps into global rings and meshes. It feeds always-on logic, power-switch inputs, and often analog or I/O through separate nets and constraints sized for aggregate current and worst-case EM. Strap pitch, width, layer, via arrays, and bump assignment are selected with early IR analysis and refined after placement and activity while preserving continuity through macro channels. It differs from the Secondary PG downstream of switches: confusing VDD and VDD_SW can bypass power gating or short domains, which LVS/ERC must detect."
  ),
  "Secondary PG": loc(
    "La Secondary Power Grid distribuisce una supply di dominio come VDD_SW, VDD_RET o VDD_LOW dalla sorgente locale alle celle dell'isola. Può essere alimentata tramite power switch, level regulator o supply dedicata e deve seguire voltage area e UPF senza connessioni accidentali alla primary grid. La sua impedenza include resistenza degli switch più mesh/rail, quindi static IR e dynamic inrush vanno analizzati per ogni power state e sequenza di accensione. Non è necessariamente always-on: retention rail e control logic possono usare una secondary AON distinta, mentre il dominio commutato viene deliberatamente corrotto quando off.",
    "The Secondary Power Grid distributes a domain supply such as VDD_SW, VDD_RET, or VDD_LOW from its local source to island cells. It may be fed through power switches, a local regulator, or a dedicated supply and must follow voltage areas and UPF without accidental connections to the primary grid. Its impedance includes switch resistance plus mesh and rails, so static IR and dynamic inrush must be analyzed for every power state and startup sequence. It is not necessarily always-on: retention rails and control logic may use a distinct secondary AON supply while the switched domain is deliberately corrupted when off."
  ),
  "Power Switch": loc(
    "Una power switch cell connette o isola una supply di dominio, normalmente con header PMOS tra VDD e VDD_SW o footer NMOS tra VSS_SW e VSS. Resistenza on-state, leakage off-state, area e current rating determinano numero e pitch delle colonne; troppi pochi switch causano IR, troppi consumano area e capacità di controllo. L'accensione viene sequenziata daisy-chain o fishbone per limitare inrush I = C·dV/dt e ground bounce, con acknowledge e always-on control definiti in UPF. Non è un isolation cell: lo switch interrompe alimentazione, mentre isolation clampa segnali di uscita e deve attivarsi prima dello spegnimento.",
    "A power-switch cell connects or isolates a domain supply, normally using a PMOS header between VDD and VDD_SW or an NMOS footer between VSS_SW and VSS. On resistance, off leakage, area, and current rating determine column count and pitch; too few switches cause IR drop, while too many consume area and control capacitance. Turn-on is sequenced as a daisy chain or fishbone to limit inrush I = C·dV/dt and ground bounce, with acknowledgment and always-on control defined in UPF. It is not an isolation cell: the switch removes supply, while isolation clamps output signals and must engage before shutdown."
  ),
  "Power Mesh": loc(
    "Una power mesh è una griglia bidimensionale di strap orizzontali e verticali, solitamente su metal alti e spessi, collegata con via array per offrire molti cammini a bassa resistance. Pitch e width derivano da corrente per regione, limiti IR ed EM e disponibilità routing; dimezzare il pitch riduce resistenza ma sottrae track ai signal e aumenta capacitance. Mesh non uniforme può rinforzare CPU, SRAM o hotspot e coordinarsi con bump map, macro ring e rail standard-cell, ma ogni transition layer deve evitare colli di bottiglia. A differenza di un semplice ring, la ridondanza 2D tollera meglio domanda distribuita e open locali, pur richiedendo extraction e signoff completi.",
    "A power mesh is a two-dimensional grid of horizontal and vertical straps, usually on thick upper metals, joined by via arrays to provide many low-resistance paths. Pitch and width derive from regional current, IR and EM limits, and routing availability; halving pitch lowers resistance but removes signal tracks and increases capacitance. A nonuniform mesh can reinforce CPUs, SRAMs, or hotspots and coordinate with bump maps, macro rings, and standard-cell rails, but every layer transition must avoid bottlenecks. Unlike a simple ring, its 2D redundancy better tolerates distributed demand and local opens while still requiring full extraction and signoff."
  ),
  "IR Drop": loc(
    "IR drop è la perdita di tensione Vdrop = I·R lungo package e PDN, che riduce la supply effettiva vista dalle celle. Static IR usa corrente media o vectorless per steady state, mentre dynamic IR include simultaneità, capacitance e package L·di/dt e può produrre droop sub-nanosecondo oltre il 10% anche con static sotto il 5%. Una tensione bassa rallenta cell delay, riduce noise margin e può causare reset o memory failure, quindi voltage map alimenta IR-aware STA e debug degli hotspot. Fix includono più bump/strap/via, power switch, decap, activity staggering o placement spreading; aumentare solo metal lontano dal collo di bottiglia può non aiutare.",
    "IR drop is voltage loss Vdrop = I·R through package and PDN, reducing the effective supply seen by cells. Static IR uses average or vectorless current for steady state, while dynamic IR includes simultaneity, capacitance, and package L·di/dt and can produce subnanosecond droop above 10% even when static loss is below 5%. Low voltage slows cell delay, reduces noise margin, and can cause reset or memory failures, so voltage maps feed IR-aware STA and hotspot debug. Fixes include more bumps, straps, vias, switches, decaps, activity staggering, or placement spreading; adding metal far from the bottleneck may not help."
  ),
  EM: loc(
    "Electromigration è il trasporto di atomi metallici dovuto a densità di corrente, capace di creare void open o hillock short nel tempo. La relazione di Black MTTF = A·J^(−n)·exp(Ea/kT) mostra la forte dipendenza da current density J e temperatura, con n tipicamente vicino a 1–2 secondo il meccanismo. Power EM valuta average/DC su strap e via, signal EM usa RMS e peak con duty cycle, e foundry table differenziano layer, width, length e via array. Un wire può essere DRC-clean ma EM-fail; widening, parallel path, via doubling, activity reduction o temperatura minore sono fix, verificati per vita target spesso 10 anni a Tmax.",
    "Electromigration is metal-atom transport driven by current density that can create open-producing voids or short-producing hillocks over time. Black's relation MTTF = A·J^(−n)·exp(Ea/kT) shows strong dependence on current density J and temperature, with n commonly near 1–2 depending on mechanism. Power EM evaluates average or DC current in straps and vias, signal EM uses RMS and peak with duty cycle, and foundry tables distinguish layer, width, length, and via arrays. A wire can be DRC-clean yet fail EM; widening, parallel paths, doubled vias, lower activity, or lower temperature are fixes verified against a lifetime target often ten years at Tmax."
  ),
  Decap: loc(
    "Una decoupling-capacitance cell immagazzina carica Q = C·V vicino al carico e fornisce corrente transiente mentre package e PDN reagiscono a di/dt. Celle MOS o MIM decap riempiono whitespace vicino a blocchi ad alta attività per ridurre dynamic droop e risonanza, ma introducono leakage, area e inrush all'accensione. La quantità utile deriva da ΔV = I·Δt/C e da simulation dell'impedenza, non dalla sostituzione indiscriminata di ogni filler, e deve rispettare density e domain supply. Una decap non corregge static IR dovuto a resistenza steady-state; per quello servono strap, via, bump o minore corrente.",
    "A decoupling-capacitance cell stores charge Q = C·V near a load and supplies transient current while the package and PDN respond to di/dt. MOS or MIM decaps fill whitespace near high-activity blocks to reduce dynamic droop and resonance, but add leakage, area, and startup inrush. Useful quantity follows ΔV = I·Δt/C and impedance simulation rather than indiscriminately replacing every filler, and it must honor density and domain supplies. A decap does not fix static IR caused by steady-state resistance; that needs straps, vias, bumps, or lower current."
  ),
  "Isolation Cell": loc(
    "Una isolation cell forza l'uscita di un dominio che può spegnersi a un valore clamp 0, clamp 1 o latch, impedendo X e livelli flottanti nel dominio ricevente acceso. UPF definisce domain boundary, sense, location e isolation signal, che deve provenire da logica always-on e attivarsi prima del power switch off. Placement sul lato source o sink dipende dalla supply disponibile, e CLP più power-aware simulation verificano missing cell, clamp polarity e sequenza. Non è un level shifter, anche se esistono celle combo: isolation gestisce validità durante power-off, mentre il level shifter gestisce ampiezza tra tensioni entrambe attive.",
    "An isolation cell forces the output of a domain that may shut down to clamp 0, clamp 1, or a latched value, preventing Xs and floating levels in a live receiving domain. UPF defines domain boundary, sense, location, and isolation control, which must come from always-on logic and assert before the power switch turns off. Source-side or sink-side placement depends on available supplies, and CLP plus power-aware simulation checks missing cells, clamp polarity, and sequence. It is not a level shifter, although combination cells exist: isolation handles validity during power-off, while level shifting handles amplitude between two active voltages."
  ),
  "Level Shifter": loc(
    "Un level shifter traduce una logica tra voltage domain, per esempio 0,65 V→0,9 V, evitando che un livello alto insufficiente o overstress violi transistor e noise margin. Low-to-high richiede una cella attiva sul rail alto, high-to-low può talvolta usare un buffer tolerant ma deve seguire le regole library e direction UPF. Delay, input slew, output load e leakage sono caratterizzati in Liberty, mentre placement al confine e secondary PG corretta sono verificati da CLP, ERC e STA. Non sostituisce isolation: se il source può spegnersi serve spesso una combo LS+ISO o due funzioni sequenziate, non un semplice translator.",
    "A level shifter translates logic between voltage domains, for example 0.65 V→0.9 V, preventing an insufficient high level or overstress from violating devices and noise margins. Low-to-high shifting needs a cell powered by the high rail, while high-to-low may sometimes use a tolerant buffer but must follow library and UPF direction rules. Delay, input slew, output load, and leakage are characterized in Liberty, while boundary placement and correct secondary power are checked by CLP, ERC, and STA. It does not replace isolation: if the source can power down, a combined LS+ISO or two sequenced functions are often required rather than a simple translator."
  ),
  Retention: loc(
    "La retention preserva stato selezionato durante power gating usando un retention FF con balloon latch o architettura master alimentata da rail always-on. Il protocollo assert save prima dell'off, mantiene VDD_RET valido e usa restore dopo power-good e clock stabilization, con isolamento coordinato per evitare dati corrotti. Retenere ogni registro aumenta area, leakage, clock load e routing AON, quindi architecture identifica solo stato necessario e ricostruisce cache o datapath quando conveniente. MBIST memory repair e retention RAM sono meccanismi diversi; CLP, simulation power-aware e STA dei save/restore path devono provare sequenza e timing.",
    "Retention preserves selected state during power gating through a retention flip-flop with a balloon latch or master element powered by an always-on rail. The protocol asserts save before shutdown, keeps VDD_RET valid, and restores after power-good and clock stabilization, with coordinated isolation to prevent corrupt data. Retaining every register increases area, leakage, clock load, and always-on routing, so architecture selects only necessary state and reconstructs caches or datapaths when practical. MBIST memory repair and RAM retention are different mechanisms; CLP, power-aware simulation, and STA of save/restore paths must prove sequence and timing."
  ),
  "Voltage Island": loc(
    "Una voltage island è una regione logica e fisica alimentata da una supply distinta per multi-voltage, DVFS o power gating. UPF power domain e voltage area guidano placement, mentre il confine richiede level shifter, isolation, retention, always-on route e una secondary PG separata secondo ogni power state. Floorplan deve allineare macro, switch, channel e bump alla corrente del dominio e prevenire celle o rail accidentalmente fuori area, verificati da CLP, ERC e IR/EM. Un clock domain non coincide necessariamente con una voltage island: un clock può attraversare più tensioni e un'isola può contenere più clock, richiedendo analisi indipendenti.",
    "A voltage island is a logical and physical region powered by a distinct supply for multivoltage operation, DVFS, or power gating. UPF power domains and voltage areas guide placement, while boundaries require level shifters, isolation, retention, always-on routing, and a separate secondary grid for each power state. Floorplanning must align macros, switches, channels, and bumps with domain current and prevent cells or rails from escaping the area, as checked by CLP, ERC, and IR/EM. A clock domain is not necessarily a voltage island: one clock may cross voltages and one island may contain several clocks, requiring independent analysis."
  ),
  "Multi-Vt": loc(
    "Multi-Vt optimization mescola celle ULVT/LVT, SVT e HVT con soglie differenti per bilanciare delay e leakage nello stesso design. LVT offre drive maggiore e setup migliore ma leakage esponenzialmente superiore, mentre HVT riduce standby power e spesso viene usato su path con slack abbondante. Synthesis e post-route optimization eseguono Vt swap senza cambiare footprint quando la library lo consente, rispettando hold, transition, IR e limiti di percentuale leakage. Vt non è supply voltage: una voltage island cambia VDD e richiede level shifting, mentre una cella HVT/LVT può condividere lo stesso rail ma deve avere viste Liberty e GDS coerenti.",
    "Multi-Vt optimization mixes ULVT/LVT, SVT, and HVT cells with different thresholds to balance delay and leakage in one design. LVT provides higher drive and better setup but exponentially greater leakage, while HVT reduces standby power and is often used on paths with abundant slack. Synthesis and post-route optimization perform Vt swaps without changing footprints when the library permits, while preserving hold, transition, IR, and leakage-percentage limits. Vt is not supply voltage: a voltage island changes VDD and needs level shifting, whereas HVT and LVT cells can share a rail but require coherent Liberty and GDS views."
  ),

  // Layout, physical verification, and process
  Fill: loc(
    "Il metal o dummy fill inserisce poligoni non funzionali per mantenere densità locale min/max e uniformità CMP su ogni layer. Può essere floating, grounded o power-connected e viene aggiunto con deck foundry window-based dopo route, rispettando exclusion analog, high-speed e keepout. Fill modifica capacitance verso ground e coupling, quindi signoff serio estrae RC fill-inclusive e ripete STA/SI; fill connesso può inoltre cambiare IR, antenna ed EM. Non è filler standard-cell: quest'ultimo occupa site, completa well/rail e implant continuity, mentre metal fill è geometria BEOL per manufacturability.",
    "Metal or dummy fill inserts nonfunctional polygons to maintain local minimum and maximum density and uniform CMP on every layer. It may be floating, grounded, or power-connected and is added with a window-based foundry deck after routing while honoring analog, high-speed, and keepout exclusions. Fill changes ground and coupling capacitance, so serious signoff performs fill-inclusive extraction and reruns STA/SI; connected fill can also affect IR, antenna, and EM. It is not a standard-cell filler: that occupies sites and completes wells, rails, and implant continuity, while metal fill is BEOL geometry for manufacturability."
  ),
  "Seal Ring": loc(
    "Il seal ring è una struttura continua multi-layer attorno al perimetro del die che protegge active area da crack di dicing, umidità, contaminazione e latch-up edge effects. Include metal, via, diffusion o guard-ring secondo la cella foundry e deve mantenere offset da scribe line, pad/bump e corner cell. Tapeout verifica continuity, width/spacing, notch e connessione a VSS o net dedicata con deck DRC/ERC qualificato, perché una discontinuità annulla il percorso meccanico/elettrico. Non è il core power ring: può condividere riferimento ground ma la sua funzione primaria è protezione del bordo e fa parte del GDS merged.",
    "A seal ring is a continuous multilayer structure around the die perimeter that protects active area from dicing cracks, moisture, contamination, and edge-related latch-up effects. It includes metal, vias, diffusion, or guard rings according to the foundry cell and must preserve offsets from the scribe line, pads or bumps, and corner cells. Tapeout checks continuity, width and spacing, notches, and connection to VSS or a dedicated net using qualified DRC/ERC decks because one discontinuity defeats the mechanical or electrical barrier. It is not the core power ring: it may share ground reference, but its primary role is edge protection and it is part of merged GDS."
  ),
  "Scribe Line": loc(
    "La scribe line o saw street è il canale tra die adiacenti sul wafer riservato a dicing laser/meccanico e strutture di controllo processo. Contiene PCM, alignment mark e test key foundry e impone keepout al seal ring per tolleranze di kerf e crack propagation. La sua larghezza riduce il numero di die per wafer e deve essere inclusa nel calcolo cost/yield, ma normalmente non appartiene alla netlist funzionale del chip. Non va confusa con die boundary: il GDS design termina al bordo autorizzato, mentre reticle assembly o foundry aggiunge scribe structures secondo il MPW o production frame.",
    "The scribe line or saw street is the channel between neighboring wafer dies reserved for laser or mechanical dicing and process-control structures. It contains foundry PCMs, alignment marks, and test keys and imposes a keepout from the seal ring for kerf and crack-propagation tolerances. Its width reduces dies per wafer and belongs in cost and yield calculations, but it normally is not part of the chip's functional netlist. It must not be confused with the die boundary: design GDS ends at the authorized edge, while reticle assembly or the foundry adds scribe structures for the MPW or production frame."
  ),
  CMP: loc(
    "Chemical Mechanical Polishing planarizza dielectric e metal combinando reazione chimica e abrasione prima dei layer successivi. Pattern troppo sparsi produce dishing, mentre densità eccessiva o pattern non uniformi produce erosion e variazioni di thickness che alterano resistance, capacitance e lithography focus. Foundry impone density min/max per finestre scorrevoli, per esempio percentuali su 50–200 µm, e fill automatico chiude i deficit mantenendo exclusion sensibili. Il DRC di density è quindi un vincolo elettrico e di yield, non cosmetico; PEX corner e CMP model possono catturare thickness variation residua dopo fill.",
    "Chemical Mechanical Polishing planarizes dielectric and metal through combined chemical reaction and abrasion before subsequent layers. Sparse patterns cause dishing, while excessive or nonuniform density causes erosion and thickness variation that changes resistance, capacitance, and lithography focus. Foundries impose minimum and maximum density over sliding windows, for example percentages across 50–200 µm, and automatic fill closes deficits while honoring sensitive exclusions. Density DRC is therefore an electrical and yield constraint rather than cosmetic; PEX corners and CMP models may capture residual thickness variation after fill."
  ),
  DRC: loc(
    "Design Rule Check confronta la geometria layout con regole foundry machine-readable per width, spacing, enclosure, extension, area, density, antenna, patterning e centinaia di relazioni context-dependent. Calibre nmDRC, Synopsys ICV e Cadence Pegasus eseguono hierarchy-aware checking sul GDS/OASIS merged con lo specifico PDK/runset locked. Tapeout richiede zero violation o waiver foundry esplicite, non soltanto zero marker nel router, perché signoff deck include regole più complete e exact layer mapping. DRC prova producibilità geometrica ma non connettività: LVS può fallire su un layout DRC-clean, e un circuito può essere DRC/LVS-clean ma fallire STA o EM.",
    "Design Rule Check compares layout geometry against machine-readable foundry rules for width, spacing, enclosure, extension, area, density, antenna, patterning, and hundreds of context-dependent relationships. Calibre nmDRC, Synopsys ICV, and Cadence Pegasus perform hierarchy-aware checks on merged GDS/OASIS with the specific locked PDK and runset. Tapeout requires zero violations or explicit foundry waivers, not merely zero router markers, because signoff decks include more complete rules and exact layer mapping. DRC proves geometric manufacturability rather than connectivity: LVS can fail on DRC-clean layout, and a DRC/LVS-clean circuit can still fail STA or EM."
  ),
  LVS: loc(
    "Layout Versus Schematic estrae device e connettività da GDS/OASIS e li confronta con la source netlist CDL/SPICE o Verilog. Calibre, ICV o Pegasus verificano net, terminal, device count, parameter W/L/multiplicity, hierarchy e supply equivalence, producendo status CORRECT solo senza mismatch non giustificati. Open, short, label errata, missing cell view e global-net mapping sono failure tipici; debug parte spesso dal primo mismatch perché errori a cascata generano migliaia di differenze. LVS non confronta forme con regole di fabbrica come DRC e non prova funzione temporale: stabilisce che il layout realizzi elettricamente la netlist firmata.",
    "Layout Versus Schematic extracts devices and connectivity from GDS/OASIS and compares them with a CDL/SPICE or Verilog source netlist. Calibre, ICV, or Pegasus checks nets, terminals, device count, W/L or multiplicity parameters, hierarchy, and supply equivalence and reports CORRECT only when no unjustified mismatch remains. Opens, shorts, wrong labels, missing cell views, and global-net mapping are common failures; debug often starts at the first mismatch because cascades create thousands of differences. LVS neither checks manufacturing geometry like DRC nor proves temporal function: it establishes that layout electrically implements the signed-off netlist."
  ),
  ERC: loc(
    "Electrical Rule Check trova condizioni elettriche rischiose non riducibili a spacing geometrico, come gate flottanti, supply short, missing well/tap, overstress, power-domain crossing e weak connection. È spesso eseguito dentro un deck LVS/PERC con conoscenza di net e device voltage, usando power-state o net class per distinguere connessioni legali. Un missing substrate tap può superare LVS connectivity ma aumentare latch-up, e un 0,65 V gate esposto a 1,8 V può essere geometricamente DRC-clean ma distruttivo. ERC differisce dal timing DRV e dal DRC: controlla topologia e condizioni elettriche, con waiver soltanto dopo review di circuit, reliability e foundry.",
    "Electrical Rule Check finds electrical hazards not reducible to geometric spacing, such as floating gates, supply shorts, missing wells or taps, overstress, power-domain crossings, and weak connections. It often runs within an LVS or PERC deck with net and device-voltage awareness, using power states or net classes to distinguish legal connections. A missing substrate tap can pass LVS connectivity yet increase latch-up, and a 0.65 V gate exposed to 1.8 V can be geometrically DRC-clean yet destructive. ERC differs from timing DRVs and DRC: it checks electrical topology and conditions, with waivers only after circuit, reliability, and foundry review."
  ),
  PV: loc(
    "Physical Verification è il gate di signoff che dimostra che il layout finale è producibile e corrisponde alla netlist mediante DRC, LVS, ERC, antenna, density, patterning e spesso DFM. Usa Calibre, ICV o Pegasus con deck foundry qualificati sulla versione PDK e sul GDS/OASIS merged comprendente IP, fill, IO e seal ring. Closure significa zero errori o waiver formalmente accettate, status LVS CORRECT, runset/checksum riproducibili e report archiviati nel tapeout package. PV non include automaticamente STA, IR/EM o functional verification: questi gate sono separati anche se condividono lo stesso layout e devono tutti essere verdi.",
    "Physical Verification is the signoff gate proving that final layout is manufacturable and matches the netlist through DRC, LVS, ERC, antenna, density, patterning, and often DFM. It uses Calibre, ICV, or Pegasus with qualified foundry decks for the locked PDK version and merged GDS/OASIS including IP, fill, I/O, and seal ring. Closure means zero errors or formally accepted waivers, LVS CORRECT status, reproducible runsets and checksums, and archived reports in the tapeout package. PV does not automatically include STA, IR/EM, or functional verification; those are separate gates even though they share the layout, and all must be green."
  ),
  DFM: loc(
    "Design For Manufacturability migliora yield e process window oltre il minimo binario richiesto dal DRC, usando redundant via, wire spreading, hotspot fixing, density balancing e lithography simulation. Un layout può essere DRC-clean ma avere pattern marginali sensibili a focus/dose, via singole critiche o line-end configuration con alta probabilità di failure. Foundry assegna score o recommended-rule violations e il team chiude target quantitativi oppure documenta waiver con impatto yield, specialmente su net clock, PG e SRAM periphery. DFM non autorizza a violare DRC mandatory: aggiunge robustezza statistica e deve essere bilanciato contro area, capacitance, timing e congestion.",
    "Design For Manufacturability improves yield and process window beyond binary minimum DRC through redundant vias, wire spreading, hotspot repair, density balancing, and lithography simulation. A layout can be DRC-clean yet contain marginal patterns sensitive to focus or dose, single critical vias, or line-end configurations with high failure probability. The foundry assigns scores or recommended-rule violations, and teams close quantitative targets or document yield-impact waivers, especially on clocks, power grids, and SRAM peripheries. DFM never permits mandatory DRC violations: it adds statistical robustness and must be balanced against area, capacitance, timing, and congestion."
  ),
  OPC: loc(
    "Optical Proximity Correction modifica le forme sulla mask con serif, bias e sub-resolution feature affinché l'immagine stampata sul wafer approssimi il layout target dopo diffraction e process effects. È eseguita dal foundry o mask shop con modelli lithography calibrati, spesso insieme a source-mask optimization e verification su focus/dose corner. Il design team non disegna normalmente le correzioni, ma deve consegnare pattern DRC/DFM e RET-clean perché hotspot irrisolvibili generano PV-band failure o richiesta di layout change. OPC non è dummy fill né double-patterning coloring: corregge trasferimento ottico di ciascuna mask, mentre coloring decide su quale mask va una feature.",
    "Optical Proximity Correction modifies mask shapes with serifs, bias, and subresolution features so the wafer image approximates target layout after diffraction and process effects. The foundry or mask shop runs it with calibrated lithography models, often together with source-mask optimization and verification across focus and dose corners. Designers normally do not draw corrections, but must deliver DRC/DFM and RET-clean patterns because uncorrectable hotspots create PV-band failures or layout-change requests. OPC is neither dummy fill nor double-patterning coloring: it corrects optical transfer on each mask, while coloring chooses which mask prints a feature."
  ),
  FEOL: loc(
    "Front End Of Line comprende well, isolation, fin o active, gate, source/drain, implant e contact necessari a fabbricare transistor prima dell'interconnect metal superiore. Le geometrie FEOL determinano device type, Vt, drive, leakage e gran parte del costo mask, con regole strettamente legate a standard-cell e analog IP qualificati. Un BTO congela questi layer e consente talvolta successivi metal-only ECO usando spare cell già presenti, mentre cambiare logica transistor richiede full respin. FEOL non è front-end design RTL: il termine qui indica fasi fisiche di processo wafer, contrapposte al BEOL di metal e via.",
    "Front End Of Line comprises wells, isolation, fins or active, gates, source/drain, implants, and contacts needed to fabricate transistors before upper interconnect. FEOL geometry determines device type, Vt, drive, leakage, and much mask cost, with rules tightly coupled to qualified standard-cell and analog IP. A BTO freezes these layers and can permit later metal-only ECOs using already placed spare cells, whereas changing transistor logic requires a full respin. FEOL is not RTL front-end design: here the term denotes physical wafer-processing stages, contrasted with BEOL metals and vias."
  ),
  BEOL: loc(
    "Back End Of Line costruisce l'interconnect sopra i transistor mediante local interconnect, metal M1…Mn, via, top metal, passivation e talvolta AP/RDL. Resistance, capacitance, current capacity e routing pitch di questo stack dominano delay di wire, SI, IR ed EM nei SoC avanzati. MTO congela le mask BEOL dopo route, fill e PV; prima di allora un metal-only ECO può riconnettere spare logic senza toccare FEOL se layer disponibili lo consentono. BEOL non include package substrate, anche se top metal e RDL creano l'interfaccia a bump o pad e richiedono co-design package.",
    "Back End Of Line builds interconnect above transistors using local interconnect, M1…Mn metals, vias, top metal, passivation, and sometimes AP/RDL. Stack resistance, capacitance, current capacity, and routing pitch dominate wire delay, SI, IR, and EM in advanced SoCs. MTO freezes BEOL masks after routing, fill, and PV; before that, a metal-only ECO may reconnect spare logic without touching FEOL if available layers permit. BEOL does not include the package substrate, although top metal and RDL form the interface to bumps or pads and require package co-design."
  ),
  FinFET: loc(
    "Un FinFET è un transistor multi-gate in cui il gate avvolge una fin verticale, migliorando controllo elettrostatico e leakage rispetto al MOS planar. La larghezza effettiva è quantizzata dal numero di fin anziché continua, mentre contacted-poly pitch e fin pitch fissano densità e opzioni di standard-cell architecture. Ai nodi 16/7/5 nm variation, self-heating, parasitic e temperature inversion richiedono modelli BSIM-CMG e characterization Liberty specifica; sizing avviene per celle discrete, non W arbitrario. FinFET non indica automaticamente il marketing node o EUV: diversi nodi usano lithography e stack differenti, e GAAFET succede al FinFET ai nodi più avanzati.",
    "A FinFET is a multigate transistor whose gate wraps a vertical fin, improving electrostatic control and leakage over planar MOS. Effective width is quantized by fin count rather than continuous, while contacted-poly pitch and fin pitch set density and standard-cell architecture options. At 16/7/5 nm, variation, self-heating, parasitics, and temperature inversion require BSIM-CMG models and specific Liberty characterization; sizing uses discrete cells rather than arbitrary W. FinFET does not automatically identify a marketing node or EUV usage: nodes use different lithography and stacks, and GAAFET succeeds FinFET at more advanced generations."
  ),
  EUV: loc(
    "Extreme Ultraviolet lithography usa luce a 13,5 nm per stampare layer critici con meno decomposition rispetto al DUV 193 nm immersion. Riduce alcuni flussi LELE/SADP e overlay tra mask, ma introduce stochastic defect, resist sensitivity, mask 3D effect e costo scanner elevato, quindi non elimina DFM o OPC. Ai nodi 7/5/3 nm soltanto layer selezionati possono essere EUV e altri restano multi-patterned DUV secondo la foundry, rendendo il layer map una parte critica del PDK. EUV è una tecnologia di fabbricazione, non una regola di routing; il designer ne vede conseguenze attraverso pitch, via, hotspot e deck signoff.",
    "Extreme Ultraviolet lithography uses 13.5 nm light to print critical layers with less decomposition than 193 nm immersion DUV. It removes some LELE or SADP flows and overlay between masks but introduces stochastic defects, resist sensitivity, mask 3D effects, and high scanner cost, so it does not eliminate DFM or OPC. At 7/5/3 nm only selected layers may use EUV while others remain multipatterned DUV by foundry choice, making layer mapping a critical PDK element. EUV is a manufacturing technology rather than a routing rule; designers see its consequences through pitches, vias, hotspots, and signoff decks."
  ),
  "Double Patterning": loc(
    "Double patterning divide un layer logico troppo denso per una singola esposizione in due mask fisiche, mediante LELE, litho-freeze-litho-etch o spacer-based SADP. Feature entro una distanza di conflitto devono avere colori opposti e il grafo deve essere bipartito; un odd cycle non è 2-colorabile senza stitch o modifica layout. Overlay tra mask, stitch e line-end aumentano variability e failure risk, quindi router, cell abutment e DRC devono essere color-aware dall'inizio. Non è la stessa cosa di EUV: EUV può ridurre il numero di split, mentre DPT descrive la decomposition indipendentemente dalla sorgente lithography.",
    "Double patterning divides a logical layer too dense for one exposure into two physical masks through LELE, litho-freeze-litho-etch, or spacer-based SADP. Features within conflict distance need opposite colors and the graph must be bipartite; an odd cycle is not two-colorable without a stitch or layout change. Mask overlay, stitches, and line ends increase variability and failure risk, so routers, cell abutment, and DRC must be color-aware from the start. It is not the same as EUV: EUV may reduce the number of splits, while DPT describes decomposition independently of the lithography source."
  ),
  "Latch-up": loc(
    "Latch-up è l'innesco del thyristor parassita PNPN formato da well e substrate CMOS, che crea un percorso a bassa impedenza tra VDD e VSS. Un transient, IO overstress o supply sequencing può superare le correnti di holding e causare consumo distruttivo finché l'alimentazione non viene rimossa. Tap cell a spacing massimo del DRM, guard ring, well tie, isolamento e controllo substrate resistance riducono i guadagni parassiti, verificati da DRC/ERC. Non è un latch logico né metastabilità: è un failure fisico di dispositivo che può superare LVS e timing se tap e current path non sono corretti.",
    "Latch-up is triggering of the parasitic PNPN thyristor formed by CMOS wells and substrate, creating a low-impedance path between VDD and VSS. A transient, I/O overstress, or supply sequencing event can exceed holding currents and cause destructive consumption until power is removed. Tap cells at the DRM maximum spacing, guard rings, well ties, isolation, and controlled substrate resistance reduce parasitic gains and are checked by DRC/ERC. It is neither a logical latch nor metastability: it is a physical device failure that can pass LVS and timing when taps or current paths are wrong."
  ),
  PDK: loc(
    "Il Process Design Kit è il pacchetto foundry versionato che rende un processo utilizzabile dai tool, includendo DRM, device model, tech LEF/file, RC tech, Liberty o collateral, DRC/LVS/ERC deck, layer map, EM rule e primitive. IP, standard-cell e flow sono qualificati su una release specifica, e il tapeout lock registra versione, option, metal stack e patch perché mixare file di release diverse invalida correlazione. Il PDK traduce dati proprietari di fabbricazione in viste per simulation, synthesis, layout, extraction e signoff, spesso con accesso e checksum controllati. Non è una singola library né un tech file: è la fonte coerente e più ampia da cui derivano tutte le viste di processo.",
    "The Process Design Kit is the versioned foundry package that makes a process usable by tools, including the DRM, device models, technology LEF or files, RC technology, Liberty or collateral, DRC/LVS/ERC decks, layer maps, EM rules, and primitives. IP, standard cells, and flows are qualified against a specific release, and tapeout lock records version, options, metal stack, and patches because mixing releases invalidates correlation. The PDK translates proprietary manufacturing data into simulation, synthesis, layout, extraction, and signoff views, often with controlled access and checksums. It is neither one library nor one tech file: it is the broader coherent source from which all process views derive."
  ),
  DRM: loc(
    "Il Design Rule Manual è la documentazione foundry autorevole che descrive layer, width, spacing, enclosure, density, antenna, latch-up, reliability e recommended rule con condizioni e figure. Il runset DRC implementa una parte machine-readable, ma note, intent, exception e regole per IP/waiver richiedono comunque lettura del DRM e tracciamento della revisione. Physical designer usa i limiti per floorplan e routing, circuit designer per device/reliability, e tapeout review verifica che option e metal stack corrispondano al prodotto. Il DRM non è il PDK completo né garantisce che un layout sia clean: i deck eseguono controlli, mentre manuale e foundry chiariscono interpretazione e waiver.",
    "The Design Rule Manual is authoritative foundry documentation describing layers, width, spacing, enclosure, density, antenna, latch-up, reliability, and recommended rules with conditions and figures. A DRC runset implements part of it in machine-readable form, but notes, intent, exceptions, and IP or waiver rules still require DRM review and revision tracking. Physical designers use its limits for floorplanning and routing, circuit designers for devices and reliability, and tapeout review confirms product options and metal stack. The DRM is neither the complete PDK nor proof that layout is clean: decks execute checks, while the manual and foundry clarify interpretation and waivers."
  ),

  // Package, tapeout, and milestones
  RDL: loc(
    "Il Redistribution Layer è un livello metallico spesso sopra la passivation o nel package che redistribuisce pad del die verso bump pitch e posizione differenti. In flip-chip e fan-out permette area-array, escape routing e power distribution, ma lunghe tracce aggiungono R, C, coupling e current-density da includere in package SI/PI e IR/EM. Width, via, under-bump metallization e keepout seguono regole package/foundry diverse dal BEOL fine-pitch e devono allinearsi alla bump map e al substrate. RDL non è un normale metal core selezionabile dal router standard-cell: richiede vista AP/RDL, extraction e spesso co-design die-package dedicato.",
    "A Redistribution Layer is thick metal above passivation or in the package that redistributes die pads to different bump pitches and locations. In flip-chip and fan-out it enables area arrays, escape routing, and power distribution, but long traces add R, C, coupling, and current density that package SI/PI and IR/EM must include. Widths, vias, under-bump metallurgy, and keepouts follow package or foundry rules distinct from fine-pitch BEOL and must align with the bump map and substrate. RDL is not an ordinary core metal chosen by the standard-cell router: it needs a dedicated AP/RDL view, extraction, and often die-package co-design."
  ),
  "Bump / C4": loc(
    "Un bump, incluso il C4 Controlled Collapse Chip Connection, è un'interconnessione saldante tra pad/RDL del die e substrate in configurazione flip-chip. Un area array con pitch tipico circa 80–150 µm offre migliaia di signal e PG connection con inductance inferiore al wire-bond, mentre microbump per 2.5D/3D può avere pitch molto minore. Diametro, current rating, bump-to-bump coupling, thermal stress e assignment VDD/VSS determinano SSO, IR/EM, escape routing e affidabilità package. Il bump non è un TSV: collega superfici di die/package, mentre il TSV attraversa verticalmente silicio bulk e può terminare su microbump.",
    "A bump, including a C4 Controlled Collapse Chip Connection, is a solder interconnect between die pad or RDL and substrate in a flip-chip assembly. An area array at roughly 80–150 µm pitch provides thousands of signal and power connections with lower inductance than wire bonds, while 2.5D or 3D microbumps may use much finer pitch. Diameter, current rating, bump coupling, thermal stress, and VDD/VSS assignment determine SSO, IR/EM, escape routing, and package reliability. A bump is not a TSV: it joins die and package surfaces, whereas a TSV passes vertically through bulk silicon and may terminate at a microbump."
  ),
  "Flip-chip": loc(
    "Il flip-chip monta il die capovolto su substrate o interposer usando bump distribuiti sull'area invece di bond wire periferici. Riduce interconnect inductance e lunghezza, supporta oltre mille I/O e porta molti bump PG vicino agli hotspot, migliorando bandwidth, SSO e PDN rispetto al wire-bond. Richiede RDL, bump map, underfill, thermal/mechanical analysis e co-design escape del substrate; warpage, bump stress e power/ground ratio sono failure mode di package signoff. Non è sinonimo di 2.5D o 3D: un singolo die flip-chip può stare su BGA, mentre interposer e stacked die aggiungono altre interconnessioni.",
    "Flip-chip mounts a die face-down on a substrate or interposer using bumps distributed across its area instead of peripheral bond wires. It shortens interconnect and lowers inductance, supports more than a thousand I/Os, and places many power bumps near hotspots, improving bandwidth, SSO, and PDN behavior over wire bonding. It requires RDL, bump-map and substrate-escape co-design, underfill, and thermal/mechanical analysis; warpage, bump stress, and power-to-ground ratio are package-signoff failure modes. It is not synonymous with 2.5D or 3D: one flip-chip die can sit on a BGA, while interposers and stacked dies add further interconnect."
  ),
  "Wire-bond": loc(
    "Il wire-bond collega pad periferici del die ai lead o substrate con fili sottili di oro, rame o alluminio mediante ball o wedge bonding. È economico e maturo per QFN, low-pin-count e analog, ma loop di alcuni millimetri aggiungono inductance e coupling che peggiorano edge veloci, SSO e ground bounce V = L·di/dt. Pad pitch, bond order, wire sweep, parallelismo e numero di power/ground bond devono essere co-simulati con modello package e IBIS. A differenza del flip-chip, gli I/O restano prevalentemente al bordo e la densità tipica è inferiore, spesso sotto alcune centinaia di connessioni pratiche.",
    "Wire bonding connects peripheral die pads to package leads or substrate with thin gold, copper, or aluminum wires using ball or wedge bonds. It is economical and mature for QFN, low-pin-count, and analog products, but millimeter-scale loops add inductance and coupling that worsen fast edges, SSO, and ground bounce V = L·di/dt. Pad pitch, bond order, wire sweep, parallelism, and power or ground wire count must be co-simulated with package models and IBIS. Unlike flip-chip, I/Os remain primarily at the perimeter and practical density is lower, often below a few hundred connections."
  ),
  SSO: loc(
    "Simultaneous Switching Output è il disturbo prodotto quando molti driver I/O commutano nello stesso intervallo, sommando di/dt su inductance condivisa di die, bump/bond e package. Ground bounce o VDD droop segue approssimativamente ΔV = Lshared·Σdi/dt e può causare false threshold crossing, jitter, EMI o timing failure sui pin quieti. Signoff usa IBIS o transistor model con package RLC, pattern worst-case, slew/drive setting e rapporto signal-to-ground realistico; non basta moltiplicare un singolo pin per N senza coupling. Fix includono staggering, drive/slew reduction, più ground bump/bond, decap e pin-map separation, distinti dal core dynamic IR pur interagendo con la stessa supply.",
    "Simultaneous Switching Output is disturbance created when many I/O drivers switch in one interval, summing di/dt through shared die, bump or bond, and package inductance. Ground bounce or VDD droop is approximately ΔV = Lshared·Σdi/dt and can cause false threshold crossings, jitter, EMI, or timing failure on quiet pins. Signoff uses IBIS or transistor models with package RLC, worst-case patterns, realistic slew and drive settings, and signal-to-ground ratios; simply multiplying one pin by N misses coupling. Fixes include staggering, reduced drive or slew, more ground bumps or bonds, decaps, and pin-map separation, distinct from but interacting with core dynamic IR."
  ),
  PKG: loc(
    "Il package è il sistema meccanico ed elettrico che collega il die alla PCB, inclusi substrate o leadframe, bump/bond, RDL, ball, lid, underfill e thermal path. Forme BGA, CSP, QFN, fan-out, 2.5D interposer e 3D stack scambiano costo, I/O density, bandwidth, inductance, heat e assembly yield. Co-design usa bump/pad map, stackup e modelli S-parameter/RLC per SI, power integrity, SSO, thermal e mechanical stress prima del tapeout die. Il package non è un contenitore passivo ideale: può dominare return path, resonance, input/output delay e temperatura, quindi constraint SDC e IBIS devono includerne i budget. Z_target = ΔV/ΔI e L_loop·di/dt guidano il budget power; escape routing e signal-to-power bump ratio decidono se la bump map è fabbricabile.",
    "The package is the mechanical and electrical system connecting die to PCB, including substrate or leadframe, bumps or bonds, RDL, balls, lid, underfill, and thermal path. BGA, CSP, QFN, fan-out, 2.5D interposer, and 3D stack options trade cost, I/O density, bandwidth, inductance, heat, and assembly yield. Co-design uses bump or pad maps, stackups, and S-parameter or RLC models for SI, power integrity, SSO, thermal, and mechanical stress before die tapeout. A package is not an ideal passive container: it can dominate return paths, resonance, I/O delay, and temperature, so SDC and IBIS budgets must include it. Z_target = ΔV/ΔI and L_loop·di/dt guide the power budget; escape routing and signal-to-power bump ratio decide whether the bump map is manufacturable."
  ),
  CPA: loc(
    "Chip–Package Analysis (CPA), estesa a Chip–Package–System (CPS), è la co-simulazione della PDN die con modelli package e spesso board per dynamic IR, |Z(f)| e voltage map. Gerarchia tipica: SPM lumpato RLC per early what-if; extracted S-parameter/RLC mesh da SIwave/Sigrity; co-sim die+package allo stesso bump port; CPS con VRM e MLCC. RedHawk-SC, Voltus e Totem importano il modello firmato sulla bump map di tapeout. Un report CPA utile mostra |Z| vs Z_target, WORST_dI/dt waveforms, gradienti spaziali e correlazione IR-aware STA. Firmare dynamic IR con un package model di revisione precedente è un failure mode classico.",
    "Chip–Package Analysis (CPA), extended to Chip–Package–System (CPS), is co-simulation of the die PDN with package and often board models for dynamic IR, |Z(f)|, and voltage maps. Typical hierarchy: lumped RLC SPM for early what-if; extracted S-parameter/RLC mesh from SIwave/Sigrity; die+package co-sim at the same bump ports; CPS with VRM and MLCCs. RedHawk-SC, Voltus, and Totem import the signed model on the tapeout bump map. A useful CPA report shows |Z| vs Z_target, WORST_dI/dt waveforms, spatial gradients, and IR-aware STA correlation. Signing dynamic IR with a prior-revision package model is a classic failure mode."
  ),
  "System PDN": loc(
    "System PDN è la catena end-to-end VRM/PMIC → plane e capacitor di board → ball BGA → package → bump/RDL → ring/strap/mesh → rail M1 → pin cella. Ogni stadio domina una banda di frequenza: bulk/VRM ai kHz, MLCC board alle MHz basse, package mid-band, on-die decap alle centinaia di MHz–GHz. Il budget IR statico e dinamico si spezza tra i pezzi; se il package consuma già la maggior parte del ΔV ammesso, la mesh on-die non può «compensare». Anti-resonance tra stadi crea picchi di |Z| tipici a 50–150 MHz. Signoff richiede correlazione board+pkg+die sulla stessa bump map e sullo stesso workload, più EM sui limiti di ciascun segmento.",
    "System PDN is the end-to-end chain VRM/PMIC → board planes and capacitors → BGA balls → package → bump/RDL → ring/strap/mesh → M1 rail → cell pin. Each stage owns a frequency band: bulk/VRM at kHz, board MLCCs at low MHz, package mid-band, on-die decap at hundreds of MHz–GHz. Static and dynamic IR budgets are split across pieces; if the package already consumes most of the allowed ΔV, the on-die mesh cannot «make up for it». Anti-resonance between stages creates typical |Z| peaks at 50–150 MHz. Signoff requires correlated board+pkg+die analysis on the same bump map and workload, plus EM against each segment's limits."
  ),
  SPM: loc(
    "Simple Package Model è un modello package lumpato (R, L, C, talvolta mutual inductance) usato in early CPA e budgeting. È veloce e utile per what-if su L_loop e C_pkg, ma non cattura multi-resonance, path multipli né gradienti spaziali come un extraction S-parameter. Se |Z(f)| diverge oltre ~20% rispetto a un modello extracted nella banda critica, lo SPM non è idoneo al signoff prodotto. Deve comunque riferire la stessa bump map e gli stessi rail name del design corrente.",
    "Simple Package Model is a lumped package model (R, L, C, sometimes mutual inductance) used in early CPA and budgeting. It is fast and useful for what-if on L_loop and C_pkg, but it does not capture multi-resonance, multiple paths, or spatial gradients like an S-parameter extraction. If |Z(f)| diverges beyond ~20% from an extracted model in the critical band, the SPM is not fit for product signoff. It must still reference the same bump map and rail names as the current design."
  ),
  "Z-target": loc(
    "Z-target (target impedance) è Z_target = ΔV_allowed / ΔI_step e definisce il tetto di |Z(f)| che board, package e die devono rispettare sulla banda di interesse. Esempio: 40 mV ammessi su uno step da 4 A ⇒ 10 mΩ. Non è una resistenza DC sola: va tracciata in frequenza fino a dove la decap on-die prende il controllo. Capacitor, ESR, L_loop e C_die spostano poli e zeri; aggiungere C indiscriminatamente può creare un nuovo picco di anti-resonance. È il linguaggio comune tra team board, package e chip PDN.",
    "Z-target (target impedance) is Z_target = ΔV_allowed / ΔI_step and sets the |Z(f)| ceiling that board, package, and die must meet across the band of interest. Example: 40 mV allowed on a 4 A step ⇒ 10 mΩ. It is not DC resistance alone: it must be traced in frequency until on-die decap takes over. Capacitors, ESR, L_loop, and C_die move poles and zeros; adding C indiscriminately can create a new anti-resonance peak. It is the common language among board, package, and chip PDN teams."
  ),
  BTO: loc(
    "Base Tape-Out è il milestone che congela e ordina le mask FEOL o base layer, inclusi well, active, gate e implant secondo la definizione foundry. Dopo BTO la funzione può cambiare soltanto se spare transistor/celle già presenti sono riconnettibili con metal futuri; aggiungere un nuovo gate richiede riaprire base mask e full respin. Il gate richiede base DRC/LVS/ERC, PDK lock, cell inventory e checksum della gerarchia consegnata, anche se route BEOL e timing finale possono essere ancora in closure. BTO non è tapeout completo né MTO: riduce schedule parallelizzando fabbricazione base, ma crea un vincolo economico forte sugli ECO successivi.",
    "Base Tape-Out is the milestone that freezes and orders FEOL or base-layer masks, including wells, active, gates, and implants under the foundry definition. After BTO, function can change only when already present spare transistors or cells can be reconnected with future metals; adding a new gate requires reopening base masks and a full respin. The gate requires base DRC/LVS/ERC, PDK lock, cell inventory, and hierarchy checksums even though BEOL routing and final timing may still be closing. BTO is neither complete tapeout nor MTO: it shortens schedule by starting base fabrication but imposes a strong economic constraint on later ECOs."
  ),
  MTO: loc(
    "Metal Tape-Out congela e consegna le mask BEOL di metal, via, fill, top layer e spesso RDL, completando la geometria funzionale del chip. Prima dell'approvazione devono essere chiusi post-route STA/SI, extraction, IR/EM, DRC/LVS/ERC, antenna, density, DFT netlist e checksum del GDS/OASIS merged secondo checklist. Dopo MTO anche un metal-only ECO cambia mask ordinate e richiede respin o costosa mask rework, quindi netlist, SPEF, DEF e layout archive devono riferire la stessa revision. MTO è successivo e più definitivo del BTO; il significato esatto dei layer inclusi resta quello del processo e contratto foundry.",
    "Metal Tape-Out freezes and delivers BEOL metal, via, fill, top-layer, and often RDL masks, completing functional chip geometry. Before approval, post-route STA/SI, extraction, IR/EM, DRC/LVS/ERC, antenna, density, final DFT netlist, and merged GDS/OASIS checksums must be closed under the checklist. After MTO even a metal-only ECO changes ordered masks and requires a respin or expensive mask rework, so netlist, SPEF, DEF, and layout archives must reference the same revision. MTO follows and is more final than BTO; the exact included layers remain defined by the process and foundry contract."
  ),
  GKC: loc(
    "GKC indica un Gate Keeper Check o Golden Kit Check, il review multidisciplinare in cui il tapeout package viene confrontato con checklist e input golden approvati. FE, DFT, PD, STA, low power, PV, IR/EM, package e project owner firmano versioni, report, waiver, checksum e residual risk; un veto mantiene il gate chiuso. Non è un singolo comando EDA né la sola esecuzione DRC: verifica coerenza tra deliverable, per esempio netlist ECO-finale, SPEF, SDC, GDS, PDK e pattern ATPG. Il nome varia per azienda o foundry, ma il principio industriale è four-eyes control e tracciabilità prima che dati irreversibili raggiungano mask shop.",
    "GKC means Gate Keeper Check or Golden Kit Check, a multidisciplinary review comparing the tapeout package against approved checklists and golden inputs. FE, DFT, PD, STA, low-power, PV, IR/EM, package, and project owners sign versions, reports, waivers, checksums, and residual risks; one veto keeps the gate closed. It is neither one EDA command nor merely a DRC run: it checks consistency among deliverables such as final-ECO netlist, SPEF, SDC, GDS, PDK, and ATPG patterns. Naming varies by company or foundry, but the industrial principle is four-eyes control and traceability before irreversible data reaches the mask shop."
  ),
  TOR: loc(
    "Tapeout Review è il meeting formale go/no-go finale che valuta evidenza di tutti i signoff e autorizza la consegna foundry. La checklist include version lock, zero o waived violations, timing/IR/EM/DFT closure, GDS/OASIS checksum, package alignment, known issue e owner signature. Un report verde ma riferito a netlist o PDK precedente non è evidenza valida, quindi TOR verifica revision matrix e riproducibilità oltre ai numeri. TOR non esegue la verifica tecnica al posto dei team: è il controllo di governance che accetta residual risk o ferma MTO quando qualunque gate è incoerente.",
    "Tapeout Review is the formal final go/no-go meeting that evaluates evidence from every signoff discipline and authorizes foundry delivery. Its checklist includes version locks, zero or waived violations, timing/IR/EM/DFT closure, GDS/OASIS checksums, package alignment, known issues, and owner signatures. A green report against an older netlist or PDK is not valid evidence, so TOR verifies the revision matrix and reproducibility in addition to metrics. TOR does not perform technical verification for the teams: it is the governance control that accepts residual risk or stops MTO when any gate is inconsistent."
  ),
  "Floorplan Exit": loc(
    "Floorplan Exit è il gate prima del placement intensivo che congela abbastanza geometria da rendere credibili area, connectivity e route feasibility. Criteri tipici includono macro FIXED senza overlap, halo/channel, pin e bump alignment, primary/secondary PG connected, voltage island, power-switch reservation, legality ed early congestion accettabile. Early timing, feedthrough, macro orientation e pin-access review devono usare netlist e constraint correnti, perché spostare una macro dopo placement può invalidare CTS, IR e schedule. Non implica timing o DRC signoff finale: dimostra che il problema fisico è ben posto e che i rischi strutturali hanno owner prima di proseguire.",
    "Floorplan Exit is the gate before intensive placement that freezes enough geometry to make area, connectivity, and routing feasibility credible. Typical criteria include FIXED nonoverlapping macros, halos and channels, pin-to-bump alignment, connected primary and secondary grids, voltage islands, power-switch reservations, legality, and acceptable early congestion. Early timing, feedthrough, macro orientation, and pin-access reviews must use current netlists and constraints because moving a macro after placement can invalidate CTS, IR, and schedule. It is not final timing or DRC signoff: it proves the physical problem is well posed and structural risks have owners before proceeding."
  ),
  "PRO Exit": loc(
    "PRO Exit è un gate di Placement/Post-Route Optimization la cui fase esatta va definita dalla metodologia, ma certifica che l'ottimizzazione corrente ha raggiunto criteri quantitativi prima del milestone successivo. Al placement exit si richiedono legality, density, congestion e pre-CTS timing entro budget; al post-route exit si richiedono route complete, internal DRC, setup/hold, DRV, antenna e SI pronti al signoff. Report devono coprire tutti gli scenario attivi e distinguere zero violation da ECO plan autorizzato, con database, netlist e constraint versionati. Non è automaticamente tapeout clean: extraction signoff, foundry PV e IR/EM restano controlli indipendenti dopo l'uscita interna del tool.",
    "PRO Exit is a Placement or Post-Route Optimization gate whose exact phase must be defined by methodology, certifying that current optimization met quantitative criteria before the next milestone. Placement exit requires legality, density, congestion, and pre-CTS timing within budget; post-route exit requires complete routing, internal DRC, setup/hold, DRVs, antenna, and SI ready for signoff. Reports must cover all active scenarios and distinguish zero violations from an authorized ECO plan, with versioned databases, netlists, and constraints. It does not automatically mean tapeout clean: signoff extraction, foundry PV, and IR/EM remain independent checks after the tool's internal exit."
  ),
  MPW: loc(
    "Un Multi-Project Wafer combina reticle area di più design sullo stesso wafer run per condividere mask e fab cost tra prototipi. Riduce drasticamente NRE per università, startup e silicon validation, ma impone die size slot, PDK option, metal stack e schedule comuni e offre numero limitato di die. Ogni progetto deve comunque superare DRC/LVS, antenna, density, reliability e data-prep del shuttle; il basso volume non giustifica signoff ridotto perché un respin attende il run successivo. MPW non è volume production né multi-die package: i design condividono la fabbricazione del wafer, non necessariamente comunicano o finiscono nello stesso package.",
    "A Multi-Project Wafer combines reticle area from several designs in one wafer run so prototypes share mask and fabrication cost. It dramatically reduces NRE for universities, startups, and silicon validation but imposes common die slots, PDK options, metal stacks, and schedules and yields only limited die quantities. Every project still must pass DRC/LVS, antenna, density, reliability, and shuttle data preparation; low volume does not justify reduced signoff because a respin waits for another run. MPW is neither volume production nor a multidie package: designs share wafer fabrication but need not communicate or enter the same package."
  ),
  Respin: loc(
    "Un respin è una nuova iterazione di mask e wafer necessaria dopo silicon bug, yield issue, late ECO o signoff escape. Un metal-only respin cambia BEOL e può riutilizzare base wafer o mask FEOL secondo processo, mentre un full respin modifica transistor/base layer e ripete BTO più MTO con costo e ciclo maggiori. Root-cause deve distinguere design, PDK/model, package, test e process, e la nuova revision ripete tutti i check impattati più regression per evitare che il fix introduca altri failure. Non è una semplice build software: mask NRE, fab lead cycle e perdita di market window rendono waiver e tapeout review estremamente conservativi.",
    "A respin is a new mask and wafer iteration required after a silicon bug, yield problem, late ECO, or signoff escape. A metal-only respin changes BEOL and may reuse base wafers or FEOL masks depending on process, while a full respin changes transistor or base layers and repeats BTO plus MTO at greater cost and cycle. Root cause must distinguish design, PDK or model, package, test, and process, and the new revision reruns all impacted checks plus regression so the fix introduces no new failures. It is not a software rebuild: mask NRE, fabrication cycle, and lost market window make waivers and tapeout review highly conservative."
  ),

  // Specialized implementation, test, and packaging concepts
  "Lock-up": loc(
    "Un lock-up latch o flip-flop viene inserito tra elementi scan di domini o clock edge differenti per interrompere il path hold Q→SI durante shift. Un latch sensibile al livello, trasparente nella fase opportuna, conserva mezzo ciclo di margine anche quando skew CTS o clock arrival dei domini è grande e non correlato. Scan stitching deve scegliere polarità e posizione, poi STA scan-shift verifica hold a frequenza TCK e in ogni modalità OCC/bypass dopo reorder fisico. Non è una delay cell: stabilizza il trasferimento inter-domain rispetto a un edge, mentre violazioni hold intra-domain normali si correggono con delay buffer.",
    "A lock-up latch or flip-flop is inserted between scan elements in different domains or on different clock edges to break the Q-to-SI hold path during shifting. A level-sensitive latch transparent in the appropriate phase preserves about half a cycle of margin even when CTS skew or domain clock arrivals are large and unrelated. Scan stitching must select polarity and location, then scan-shift STA checks hold at TCK frequency in every OCC or bypass mode after physical reordering. It is not a delay cell: it stabilizes an interdomain transfer relative to an edge, while ordinary intradomain hold violations use delay buffers."
  ),
  OCC: loc(
    "Un On-Chip Clock Controller controlla i clock di test selezionando slow scan clock o PLL funzionale e generando uno o pochi pulse at-speed per launch/capture transition ATPG. Include mux, synchronizer, enable e pulse generator progettati glitch-free, con protocollo che carica le chain lentamente e cattura a frequenza operativa senza impulsi extra. Per CTS è un clock root o branch speciale; SDC deve modellare bypass e capture clock, mentre STA controlla gating, min pulse width, recovery e relazione tra domini. OCC non è un PLL né un ICG ordinario: orchestra pattern di test e controllabilità clock, ma riusa principi di mux/gating sicuri e deve essere integrato con DFT e ATPG.",
    "An On-Chip Clock Controller selects slow scan clocks or functional PLL clocks and generates one or a few at-speed pulses for launch/capture transition ATPG. It includes glitch-free muxes, synchronizers, enables, and pulse generation under a protocol that loads chains slowly and captures at operating frequency without extra pulses. For CTS it is a special clock root or branch; SDC must model bypass and capture clocks, while STA checks gating, minimum pulse width, recovery, and domain relationships. An OCC is neither a PLL nor an ordinary ICG: it orchestrates test patterns and clock controllability while reusing safe mux and gating principles and integrating with DFT and ATPG."
  ),
  EDT: loc(
    "Embedded Deterministic Test è un'architettura di scan compression che collega pochi canali ATE a molte chain interne tramite decompressor in ingresso, compactor/MISR in uscita e X masking. Un rapporto 100× può ridurre pin, pattern data e test time mantenendo coverage ATPG, ma dipende da chain balance, X source, diagnosability e limiti di shift/capture power. Tessent EDT genera hardware e pattern che devono restare coerenti con netlist ECO-finale, OCC, lock-up e physical scan reorder e vengono verificati con simulation e DFT rule checks. Non è random LBIST: i pattern restano deterministicamente calcolati dall'ATPG, mentre il codec on-chip espande e comprime l'informazione.",
    "Embedded Deterministic Test is a scan-compression architecture connecting a few ATE channels to many internal chains through an input decompressor, output compactor or MISR, and X masking. A 100× ratio can reduce pins, pattern data, and test time while preserving ATPG coverage, but depends on chain balance, X sources, diagnosability, and shift or capture power limits. Tessent EDT generates hardware and patterns that must remain coherent with the final-ECO netlist, OCC, lock-ups, and physical scan reordering and are checked through simulation and DFT rules. It is not random LBIST: patterns remain deterministically computed by ATPG, while the on-chip codec expands and compacts information."
  ),
  HFNS: loc(
    "High Fanout Net Synthesis costruisce buffer tree per reset, scan_enable, test_mode, isolation enable e altre net non-clock con migliaia o 10k–100k sink. Limita transition, capacitance, fanout e delay distribuendo driver e talvolta routing NDR, preservando polarità, reset recovery/removal e controllabilità DFT. Placement-aware clustering evita lunghi branch e congestion, e STA verifica sia functional sia test/power mode perché un reset tree lento può rilasciare registri in cicli differenti. HFNS non è CTS: ottimizza slew e distribuzione ma normalmente non richiede skew di pochi picosecondi, duty cycle o clock-cell-only topology.",
    "High Fanout Net Synthesis builds buffer trees for reset, scan_enable, test_mode, isolation enables, and other nonclock nets with thousands or 10k–100k sinks. It limits transition, capacitance, fanout, and delay by distributing drivers and sometimes NDR routing while preserving polarity, reset recovery/removal, and DFT controllability. Placement-aware clustering avoids long branches and congestion, and STA checks functional, test, and power modes because a slow reset tree may release registers in different cycles. HFNS is not CTS: it optimizes slew and distribution but normally does not require picosecond skew, duty-cycle control, or a clock-cell-only topology."
  ),
  LELE: loc(
    "Litho-Etch-Litho-Etch è una forma di double patterning in cui due esposizioni e due etch separati stampano colori complementari dello stesso layer logico. Il decomposition graph collega feature entro conflict spacing e deve essere 2-colorabile; un ciclo dispari richiede stitch o modifica di placement/routing e viene riportato come DRC, non warning opzionale. Overlay tra i due passaggi e differenze CD introducono variazione color-dependent, perciò celle, abutment e router devono rispettare coloring e same/different-mask spacing. LELE differisce da SADP spacer-based e da EUV single exposure, pur mirando allo stesso pitch che il processo ottico singolo non risolve.",
    "Litho-Etch-Litho-Etch is a double-patterning form in which two separate exposures and etches print complementary colors of one logical layer. The decomposition graph connects features within conflict spacing and must be two-colorable; an odd cycle needs a stitch or placement or routing change and is reported as a DRC rather than an optional warning. Overlay between passes and CD differences introduce color-dependent variation, so cells, abutments, and routers must honor coloring and same- or different-mask spacing. LELE differs from spacer-based SADP and single-exposure EUV while addressing pitch that one optical pass cannot resolve."
  ),
  "PV-band": loc(
    "PV-band, o process-variation band in lithography verification, è l'inviluppo tra i contorni stampati estremi previsti su corner di focus, dose, mask e processo attorno al target layout. Una banda larga o che invade una feature vicina segnala scarso process window: line-end può accorciarsi, uno spazio può chiudersi o un via landing può perdere overlap pur con nominal DRC pulito. Foundry OPC/DFM flow confronta band e contour contro limiti e hotspot library, e il layout team corregge spacing, jog, line-end o pattern density prima della mask release. Non è PVT timing variation né una normale DRC rectangle; è evidenza geometrica probabilistica del comportamento lithography dopo RET/OPC.",
    "PV-band, or process-variation band in lithography verification, is the envelope between extreme printed contours predicted across focus, dose, mask, and process corners around target layout. A wide band or one intruding into a neighbor signals poor process window: line ends may shorten, spaces may close, or via landings may lose overlap despite clean nominal DRC. Foundry OPC/DFM flow compares bands and contours against limits and hotspot libraries, and layout teams repair spacing, jogs, line ends, or pattern density before mask release. It is neither PVT timing variation nor an ordinary DRC rectangle; it is geometric probabilistic evidence of post-RET or OPC lithography behavior."
  ),
  FO4: loc(
    "Fan-Out of 4 è il delay di un inverter di riferimento che pilota quattro inverter identici e serve come unità normalizzata di profondità logica. Se tFO4 è 12 ps e il ciclo utile dopo clock overhead è 360 ps, il budget teorico è circa 30 FO4, prima di wire, variation e margin. Microarchitetti confrontano pipeline e nodi con FO4/cycle, ma implementation usa delay Liberty/RC reali perché tFO4 varia con PVT, Vt, slew e definizione della cella. FO4 non è max_fanout quattro né un constraint di synthesis: è una metrica tecnologica e architetturale che perde precisione quando interconnect domina.",
    "Fan-Out of 4 is the delay of a reference inverter driving four identical inverters and serves as a normalized unit of logic depth. If tFO4 is 12 ps and usable cycle time after clock overhead is 360 ps, the theoretical budget is about 30 FO4 before wires, variation, and margin. Microarchitects compare pipelines and nodes through FO4 per cycle, but implementation uses actual Liberty and RC delays because tFO4 varies with PVT, Vt, slew, and reference-cell definition. FO4 is neither a maximum fanout of four nor a synthesis constraint: it is a technology and architecture metric that loses precision when interconnect dominates."
  ),
  ICG: loc(
    "Una Integrated Clock Gating cell combina latch level-sensitive e AND/OR, oppure equivalente library, per abilitare il clock senza glitch mentre la fase attiva è protetta. L'enable viene catturato durante la fase sicura e deve rispettare clock-gating setup/hold Liberty; un test-enable forza il clock in scan e ATPG. Synthesis inferisce o inserisce ICG da enable comuni, CTS le tratta come sink/root di branch e STA verifica pulse width, transition, latency e gating check in tutti i mode. Una porta AND combinazionale sul clock non è equivalente e può generare runt pulse o doppio edge capaci di corrompere stato e violare DFT.",
    "An Integrated Clock Gating cell combines a level-sensitive latch with an AND or OR, or a library equivalent, to enable a clock without glitches while protecting the active phase. The enable is captured during the safe phase and must meet Liberty clock-gating setup and hold; a test enable forces clocks during scan and ATPG. Synthesis infers or inserts ICGs from common enables, CTS treats them as branch sinks or roots, and STA checks pulse width, transition, latency, and gating checks in every mode. A combinational AND on a clock is not equivalent and can create runt pulses or double edges that corrupt state and violate DFT."
  ),
  CRPR: loc(
    "Clock Reconvergence Pessimism Removal corregge STA quando launch e capture clock condividono un tratto o divergono e riconvergono, al quale early e late variation sono stati applicati in modo mutuamente impossibile. Il tool identifica il common point e accredita la differenza di delay, per esempio 8 ps, allo slack senza modificare fisicamente il circuito. Edge, transition, waveform, mux exclusivity e derate devono essere compatibili; report dettagliato deve mostrare il valore per evitare credito su path che non condividono davvero lo stesso evento. CRPR è spesso usato come sinonimo o caso specifico di CPPR e rimuove solo pessimismo analitico, non jitter, skew fisico o una violazione dati reale.",
    "Clock Reconvergence Pessimism Removal corrects STA when launch and capture clocks share a segment or diverge and reconverge, and mutually impossible early and late variation was applied to that segment. The tool identifies the common point and credits the delay difference, for example 8 ps, back to slack without physically changing the circuit. Edges, transitions, waveforms, mux exclusivity, and derates must be compatible; detailed reports must show the value so no credit is granted to paths that do not truly share the event. CRPR is often used synonymously with or as a specific case of CPPR and removes only analytical pessimism, not jitter, physical skew, or a real data violation."
  ),
  DPT: loc(
    "Double Patterning Technology è l'insieme di processi e regole che decompone un layer denso in due mask, includendo LELE e varianti spacer-based secondo il nodo. Layout-aware coloring assegna A/B alle feature entro conflict distance e vieta odd cycle, stitch rischiosi e combinazioni di via o line-end non stampabili. P&R usa track e cell color compatibility, mentre signoff deck esegue decomposition indipendente sul GDS merged perché un abutment gerarchico può creare conflitti invisibili localmente. DPT è il termine generale di tecnologia; LELE specifica una sequenza litho-etch, e OPC corregge la forma ottica dopo l'assegnazione mask.",
    "Double Patterning Technology is the family of processes and rules that decomposes a dense layer into two masks, including LELE and spacer-based variants by node. Layout-aware coloring assigns A or B to features within conflict distance and forbids odd cycles, risky stitches, and unprintable via or line-end combinations. P&R uses track and cell-color compatibility, while signoff decks independently decompose merged GDS because hierarchical abutment can create conflicts invisible locally. DPT is the general technology term; LELE names a litho-etch sequence, and OPC corrects optical shape after mask assignment."
  ),
  BISR: loc(
    "Built-In Self Repair aggiunge logica di diagnosi e configurazione che sostituisce row o column SRAM difettose con spare disponibili dopo MBIST. Un repair analyzer converte failing address in redundancy signature, salvata in eFuse, OTP o registro e caricata al boot per programmare mux di row/column. Yield gain dipende da spare count e distribuzione dei defect; per esempio una memoria con una spare row non ripara due failure in row indipendenti, quindi simulation fault-injection e redundancy analysis sono obbligatori. BISR non è MBIST: MBIST applica March pattern e rileva failure, mentre BISR decide una soluzione riparabile e deve essere ritestato dopo programming.",
    "Built-In Self Repair adds diagnosis and configuration logic that replaces faulty SRAM rows or columns with available spares after MBIST. A repair analyzer converts failing addresses into a redundancy signature stored in eFuse, OTP, or registers and loaded at boot to program row or column muxes. Yield gain depends on spare count and defect distribution; for example, one spare row cannot repair two failures in independent rows, so fault-injection simulation and redundancy analysis are mandatory. BISR is not MBIST: MBIST applies March patterns and detects failures, while BISR chooses a repair solution that must be retested after programming."
  ),
  SDFF: loc(
    "Uno Scan D Flip-Flop è un FF con mux interno o pin SI/SE che seleziona tra functional D e scan input, collegandosi serialmente in test mode. In functional mode deve essere equivalente al FF originale, mentre in shift mode clock lento sposta stato e in capture mode uno o due pulse OCC campionano la risposta at-speed. Liberty contiene archi D/SI/SE/CK e constraint aggiuntivi, LEF aggiunge pin-access pressure e scan replacement può aumentare area, clock load e hold sensitivity. SDFF non significa che il chip sia DFT-complete: chain stitching, lock-up, ATPG coverage, compression e timing scan devono ancora essere chiusi.",
    "A Scan D Flip-Flop is a flip-flop with an internal mux or SI and SE pins selecting functional D versus scan input and connecting serially in test mode. In functional mode it must be equivalent to the original FF, while slow scan clocks shift state and one or two OCC pulses capture the at-speed response. Liberty contains D/SI/SE/CK arcs and added constraints, LEF adds pin-access pressure, and scan replacement can increase area, clock load, and hold sensitivity. An SDFF does not make a chip DFT-complete: chain stitching, lock-ups, ATPG coverage, compression, and scan timing still require closure."
  ),
  GRC: loc(
    "Global Route Congestion è la stima di domanda e capacità prodotta dal global router quando assegna topologie e layer a GCell senza definire ogni shape detailed-route. Metriche includono horizontal/vertical overflow, edge utilization demand/capacity e hotspot score; un edge a 0,8 può essere warning, mentre valori oltre 1,0 indicano domanda superiore alla capacità secondo la definizione del tool. La mappa guida placement spreading, macro channel, blockage, pin assignment e layer reservation prima che detailed route trasformi pressione in DRC e detour reali. GRC non è una percentuale universale: soglie dipendono da tool, layer e metodologia e vanno correlate con route completion e search-and-repair.",
    "Global Route Congestion is the demand and capacity estimate produced when a global router assigns topologies and layers to GCells without creating every detailed-route shape. Metrics include horizontal or vertical overflow, edge utilization as demand over capacity, and hotspot scores; an edge at 0.8 may warn, while values above 1.0 mean demand exceeds capacity under the tool definition. The map guides placement spreading, macro channels, blockages, pin assignment, and layer reservations before detailed routing turns pressure into real DRCs and detours. GRC is not a universal percentage: thresholds depend on tool, layer, and methodology and must correlate with route completion and search-and-repair."
  ),
  IBIS: loc(
    "I/O Buffer Information Specification è un modello comportamentale standard che descrive curve pull-up/pull-down, clamp, package RLC, ramp o waveform e corner senza rivelare transistor proprietari. Simulatori board/package usano IBIS per signal integrity, overshoot, undershoot, ringing, crosstalk e SSO con stackup e termination reali a velocità molto maggiore di SPICE. La qualità dipende da model validation, fixture, V/T corner, pin package model e receiver threshold; un modello typ non firma worst-case timing o overstress. IBIS non definisce set_input_delay/set_output_delay direttamente: la simulazione channel produce budget e flight time che vengono poi tradotti nei constraint SDC.",
    "I/O Buffer Information Specification is a standard behavioral model describing pull-up and pull-down curves, clamps, package RLC, ramps or waveforms, and corners without disclosing proprietary transistors. Board and package simulators use IBIS for signal integrity, overshoot, undershoot, ringing, crosstalk, and SSO with real stackups and terminations much faster than SPICE. Quality depends on model validation, fixtures, voltage and temperature corners, pin package models, and receiver thresholds; a typical model does not sign off worst-case timing or overstress. IBIS does not directly define set_input_delay or set_output_delay: channel simulation produces budgets and flight times later translated into SDC constraints."
  ),
  DVFS: loc(
    "Dynamic Voltage and Frequency Scaling cambia VDD e clock durante funzionamento per ridurre energia, sfruttando P_dyn = α·C·V²·f e il tradeoff delay-tensione. Ogni operating performance point combina voltage, frequency, PLL/divider state e spesso body bias, con sequenze sicure che abbassano f prima di V e alzano V prima di f. MMMC, UPF/CLP, STA, IR/EM e power analysis devono coprire gli OPP legali, inclusi transition state, level shifter, regulator settling e clock switching. DVFS non è semplice clock gating: gating porta activity/f a zero localmente senza cambiare V, mentre DVFS cambia corner elettrico e può richiedere voltage island e firmware control.",
    "Dynamic Voltage and Frequency Scaling changes VDD and clock during operation to reduce energy, exploiting P_dyn = α·C·V²·f and the delay-voltage tradeoff. Each operating performance point combines voltage, frequency, PLL or divider state, and sometimes body bias, with safe sequences that lower frequency before voltage and raise voltage before frequency. MMMC, UPF/CLP, STA, IR/EM, and power analysis must cover legal OPPs including transition states, level shifters, regulator settling, and clock switching. DVFS is not simple clock gating: gating locally drives activity or frequency to zero without changing V, while DVFS changes the electrical corner and may require voltage islands and firmware control."
  ),
  HBM: loc(
    "High Bandwidth Memory è una pila 3D di die DRAM collegati con TSV e microbump a un base die, affiancata al logic die su interposer o advanced package. Un'interfaccia molto larga, spesso 1024 bit per stack e più canali, offre centinaia di GB/s o oltre a frequenza per pin moderata e minore energia/bit rispetto a GDDR. Co-design deve chiudere PHY timing, bump map, interposer SI/PI, repair/training, thermal gradient e power delivery, perché stack e logic hotspot condividono un severo limite termico. HBM non è cache on-chip né un semplice DDR package: usa protocollo JEDEC, controller/PHY dedicato e yield/test di più die integrati.",
    "High Bandwidth Memory is a 3D stack of DRAM dies connected through TSVs and microbumps to a base die, placed beside a logic die on an interposer or advanced package. A very wide interface, commonly 1024 bits per stack across multiple channels, provides hundreds of GB/s or more at moderate per-pin frequency and lower energy per bit than GDDR. Co-design must close PHY timing, bump maps, interposer SI/PI, repair and training, thermal gradients, and power delivery because stack and logic hotspots share a severe thermal limit. HBM is neither on-chip cache nor a simple DDR package: it uses a JEDEC protocol, dedicated controller and PHY, and multidie yield and test."
  ),
  TSV: loc(
    "Un Through-Silicon Via è un conduttore verticale inciso attraverso un die di silicio o interposer e riempito con rame o altro materiale per collegare superficie frontale e posteriore. Diametro, profondità e pitch determinano parassiti RLC e keepout di stress, mentre liner capacitance, espansione termica e copper pumping influenzano SI, mobilità dei device e affidabilità. Array TSV trasportano dati, clock e power HBM negli stack 3D e richiedono allineamento microbump, backside processing, accesso test, ridondanza e floorplan termicamente consapevole. Un TSV non è una normale via BEOL né un bump saldante: attraversa decine o centinaia di micrometri di silicio bulk, mentre le via attraversano dielectric e i bump uniscono superfici separate.",
    "A Through-Silicon Via is a vertical conductor etched through a silicon die or interposer and filled with copper or another conductor to connect front and back surfaces. Diameter, depth, and pitch determine RLC parasitics and stress keepouts, while liner capacitance, thermal expansion, and copper pumping affect SI, device mobility, and reliability. TSV arrays carry HBM data, clocks, and power in 3D stacks and require microbump alignment, backside processing, test access, redundancy, and thermal-aware floorplanning. A TSV is not an ordinary BEOL via or solder bump: it traverses bulk silicon over tens to hundreds of micrometers, whereas vias cross dielectrics and bumps join separate surfaces."
  ),
};
